module ddPCRProteinDetection
module rtDdPCRmRNADetection
module liveCellImagingDetection
module viralProteinDetection

manifest PBS
manifest LysisBuffer
manifest PLAProbes
manifest LigationMix
manifest MilliQWater
manifest BSA_BlockingBuffer
manifest SingleCell
manifest PurifiedProteinStandard
manifest RNaseOUT
manifest RTddPCR_Supermix
manifest ReversTranscriptase
manifest DTT
manifest UniversalPCRAssay
manifest TaqMan_TNFR1_Probe
manifest ddPCR_Supermix
manifest DropletGenerationOil
manifest HFE7500_Surfactant
manifest HSV1_InfectedCell
manifest ControlCell

// ============================================================
// Ultra-sensitive Digital Quantification of Proteins and mRNA
// in Single Cells (u-dPLA)
// Lin et al., Nature Communications (2019) 10:3544
// DOI: https://doi.org/10.1038/s41467-019-11531-z
//
// OVERVIEW:
// Automated microfluidic digital proximity ligation assay
// (u-dPLA) for ultrasensitive, single-cell quantification of
// proteins (via ddPCR readout of PLA products) and mRNA (via
// one-step RT-ddPCR), simultaneously from the same single cell.
//
// KEY PERFORMANCE METRICS:
//   LOD (TNFR1):  2,277 protein molecules per cell
//   LOD (CD147):  2,795 protein molecules per cell
//   LOD (CSTB):  18,824 protein molecules per cell
//   Detection efficiency (CD147): as low as 29 protein molecules
//   Improvement over regular dPLA: up to 55x better LOD
//   Linear dynamic range: 3-4 orders of magnitude
//   Chip capacity: 144 parallel single-cell dPLA assays
//   Chamber (trap) volume: 7 nL
//   Sample used in ddPCR: 100% (vs 9% in regular dPLA)
//   Pipetting error: <0.1% (vs ~10% manual)
//
// CHIP ARCHITECTURE (one assay unit, Chambers I-V):
//   Chamber I:   Reagent input / wash channel
//   Chamber II:  Single-cell trap (hydrodynamic, 50 um constriction)
//   Chamber III: 7-nL lysis chamber; cell lysed here; probe incubation
//   Chamber IV:  Probe-lysate diffusion mixing zone
//   Chamber V:   Ligation reaction chamber
//   Output port: PLA products retrieved for ddPCR/RT-ddPCR
//
// FABRICATION NOTE: Two-layer push-up PDMS device.
//   Control layer (thin): microfluidic valves (SU-8 22 um),
//     operated by Matlab-controlled pneumatic actuators.
//   Fluidic layer (thick): reagent channels (SU-8 70 um + AZ 18 um).
//   Chambers sealed by dead-end filling for precise nanoliter volumes.
//   Wash channels prevent cross-contamination between steps.
//
// BIOSCRIPT ABSTRACTIONS:
//   - `mix X with Y for T` abstracts valve-gated reagent introduction
//     and diffusion-based mixing inside closed nanoliter chambers.
//     No DMF electrode actuation is involved; fluid movement is driven
//     by pneumatic pressure and Matlab-controlled valve sequencing.
//   - `heat` abstracts on-chip or bench incubation steps with
//     temperature control (enzyme steps, ligation, etc.).
//   - Duration tokens follow BioScript compiler constraints:
//     s (seconds) and m (minutes) only; hours converted to minutes.
//   - Cell occupancy: ~90% average per assay run; a single cell is
//     modelled as one `SingleCell` manifest unit per assay unit.
//   - ddPCR/RT-ddPCR readout is modelled via detect modules;
//     actual droplet generation and thermal cycling occur off-chip
//     after product retrieval.
//
// CFG STRUCTURE:
//   BB1  main                -- chip prep, calibration curve,
//                               single-cell trap, lysis, PLA, ligation,
//                               product retrieval, ddPCR QC gate
//   BB2  proteinPass         -- proteinSignal > 0: valid protein count;
//                               dispose lysate, continue to mRNA branch
//   BB3  proteinFail         -- proteinSignal <= 0: below LOD; drain
//   BB4  proteinJoin         -- join: duplex mRNA/protein branch begins
//   BB5  mrnaPass            -- mrnaSignal > 0: valid mRNA count; dispose
//   BB6  mrnaFail            -- mrnaSignal <= 0: no mRNA detected; drain
//   BB7  mrnaJoin            -- join: HSV-1 viral infection branch begins
//   BB8  infectionPass       -- infectionSignal > 0: ICP4-YFP+ infected
//                               cell; dispose viral protein readout
//   BB9  infectionFail       -- infectionSignal <= 0: uninfected or
//                               abortive; drain
//   BB10 finalCleanup        -- terminal: dispose all QC signals
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: Block non-specific binding.
//   Chip surface coated with 10% BSA in PBS for 1 h at RT
//   to minimise non-specific adsorption of PLA probes and
//   cell-lysate proteins to PDMS channel walls.
//   After incubation, chip is washed with MilliQ water and
//   ventilated with compressed air before cell loading.
//   1 h = 60 min.
// ------------------------------------------------------------

bsaBlock     = dispense 1 units of BSA_BlockingBuffer
pbsWash0     = dispense 1 units of PBS

chipSurface  = mix bsaBlock with pbsWash0 for 60m

// Wash off excess BSA with MilliQ water.
waterWash0   = dispense 1 units of MilliQWater
blockedChip  = mix chipSurface with waterWash0 for 5m

// ------------------------------------------------------------
// STEP 2: Calibration curve (on-chip, performed in parallel
//   with single-cell experiments on same chip run).
//   Serial dilution of purified protein standard (e.g., TNFR1,
//   CD147, or CSTB) loaded from lowest to highest concentration.
//   8 min washing between standards through Channel I.
//   Calibration units are loaded into chambers I-V by the
//   same dead-end filling protocol as single-cell samples.
//   PLA probes: 500 pM stock, diluted to 2 nM working solution
//   in probe binding buffer (0.1% BSA, 0.05% Tween-20,
//   100 nM goat IgG, 0.1 g/L sheared salmon sperm DNA in PBS).
//   NOTE: `mix` abstracts sequential dead-end filling of each
//   calibration concentration into the assay chambers.
// ------------------------------------------------------------

proteinStd   = dispense 1 units of PurifiedProteinStandard
probeWash1   = dispense 1 units of PBS

// Load calibration standard into chamber III (7 nL).
stdInChamber = mix proteinStd with probeWash1 for 2m

// Flush Channel I and II with PLA probes (500 pM -> 2 nM).
plaProbeStd  = dispense 1 units of PLAProbes
stdProbeIncub = mix stdInChamber with plaProbeStd for 60m

// ------------------------------------------------------------
// STEP 3: Load ligation mix into calibration chambers.
//   Ligation mix (per 100 uL): 89.1 uL MilliQ water,
//   10 uL 10x ligase buffer, 0.4 uL 1/500-diluted T4 ligase,
//   0.5 uL 1 uM connector oligonucleotide.
//   Pushed from chambers III/IV to chamber V.
//   30 min on ice for diffusion mixing; 10 min ligation at 37 C;
//   5 min heat inactivation at 65 C.
//   Modelled as three sequential heat steps on the same droplet.
// ------------------------------------------------------------

ligMixStd    = dispense 1 units of LigationMix
stdLigMix    = mix stdProbeIncub with ligMixStd for 30m

// Ligation: 37 C for 10 min.
heat stdLigMix at 37c for 10m

// Heat inactivation of T4 ligase: 65 C for 5 min.
heat stdLigMix at 65c for 5m

// Retrieve calibration PLA products (9 uL) for ddPCR.
waterFlush1  = dispense 1 units of MilliQWater
stdProducts  = mix stdLigMix with waterFlush1 for 2m

// ============================================================
// SINGLE-CELL u-dPLA ASSAY
// ============================================================

// ------------------------------------------------------------
// STEP 4 (Chamber II): Single-cell loading and trapping.
//   Cells resuspended in sterile PBS, filtered through 40 um
//   strainer, diluted to 2x10^5 cells/mL.
//   Loaded at 5 psi input pressure into Channel I.
//   Single cells are hydrodynamically trapped in Chamber II
//   (50 um constriction) with ~90% average occupancy.
//   Cell loading verified visually under microscope before
//   proceeding. Chip immediately moved to ice after loading.
//   NOTE: `mix` abstracts pressure-driven cell loading into
//   the hydrodynamic trap; no reagent mixing in the DMF sense.
// ------------------------------------------------------------

singleCell   = dispense 1 units of SingleCell
pbsTrap      = dispense 1 units of PBS

trappedCell  = mix singleCell with pbsTrap for 2s

// ------------------------------------------------------------
// STEP 5 (Chamber III): Single-cell lysis.
//   Lysis buffer: 0.3x TM buffer + protease inhibitor in cell
//   resuspension buffer. Introduced from Chamber I to push and
//   lyse the trapped cell from Chamber II into Chamber III (7 nL).
//   Lysis complete within 10 min on ice. Visually confirmed
//   under microscope. Entire 7-nL lysate remains in Chamber III;
//   zero sample loss (cf. regular dPLA: 91% sample loss).
//   Reducing dilution factor is the primary source of 55x
//   sensitivity improvement over regular well-plate dPLA.
// ------------------------------------------------------------

lysisBuffer  = dispense 1 units of LysisBuffer
cellLysate   = mix trappedCell with lysisBuffer for 10m

// Chip maintained on ice during lysis (modelled as 0 C, 10 min).
heat cellLysate at 0c for 10m

// ------------------------------------------------------------
// STEP 6 (Chambers III-IV): PLA probe incubation with lysate.
//   PLA probes (oligonucleotide-tagged antibody pairs) flushed
//   through Channels I and II into Chamber III. Probe-lysate
//   mix occupies Chambers III and IV with valve between open.
//   Incubated at 37 C for 1 h. Diffusion-based mixing.
//   Antibody pairs recognise two distinct epitopes on target
//   protein. Proximity ligation requires both probes bound
//   to the same protein molecule within ~3-5 nm.
//   PLA probes: TNFR1: BAF225; CD147: BAF972 (R&D Systems).
//   HSV-1: anti-HSV-1 polyclonal (ab9533, Abcam) conjugated
//   in-house via DBCO-NHS/azide click chemistry.
//   1 h = 60 min.
// ------------------------------------------------------------

plaProbeCell = dispense 1 units of PLAProbes
probeIncub   = mix cellLysate with plaProbeCell for 60m

// Incubate at 37 C for 1 h.
heat probeIncub at 37c for 60m

// ------------------------------------------------------------
// STEP 7 (Chamber V): Ligation reaction.
//   Ligation mix introduced from Channels I/II to push the
//   probe-lysate mix (Chambers III/IV) into Chamber V.
//   Connector oligonucleotide (TTTCGACACGACACGATTTAGGTC)
//   bridges the two probe oligonucleotides when both probes
//   are bound to the same target protein.
//   T4 DNA ligase seals the nick to form a circular DNA product.
//   30 min on ice for diffusion mixing (valve between III and V
//   open); then 37 C for 10 min ligation; 65 C for 5 min
//   heat inactivation of T4 ligase.
// ------------------------------------------------------------

ligMixCell   = dispense 1 units of LigationMix
ligOnIce     = mix probeIncub with ligMixCell for 30m

heat ligOnIce at 0c for 30m
heat ligOnIce at 37c for 10m
heat ligOnIce at 65c for 5m

// ------------------------------------------------------------
// STEP 8: Retrieve PLA products for ddPCR.
//   PLA products flushed out of Chamber V by MilliQ water
//   through the output retrieval port (1930 um punch) into
//   a collection tube. 9 uL retrieved per unit.
//   ddPCR Supermix for Probes (Bio-Rad QX200) + Universal
//   PCR Assay added; 20 uL total loaded into DG8 cartridge
//   with 65 uL Droplet Generation Oil for droplet generation.
//   PCR program: 95 C 10 min; 40x (94 C 30s / 60 C 1 min);
//   98 C 10 min; ramp 1.5 C/s.
//   FAM channel readout: counts positive droplets containing
//   ligated PLA DNA product. Each positive droplet = 1 protein.
// ------------------------------------------------------------

waterFlush2  = dispense 1 units of MilliQWater
plaProducts  = mix ligOnIce with waterFlush2 for 2m

ddpcrMix     = dispense 1 units of ddPCR_Supermix
universalPCR = dispense 1 units of UniversalPCRAssay
dropletOil   = dispense 1 units of DropletGenerationOil

// Assemble ddPCR reaction mix.
ddpcrRxn1    = mix plaProducts with ddpcrMix for 5s
ddpcrRxn2    = mix ddpcrRxn1 with universalPCR for 5s
ddpcrLoaded  = mix ddpcrRxn2 with dropletOil for 5s

// ddPCR thermal cycling: 95 C 10 min activation.
heat ddpcrLoaded at 95c for 10m

// 40 amplification cycles: 94 C 30s + 60 C 1 min = 90s each.
// 40 cycles x 90s = 3600s = 60m.
heat ddpcrLoaded at 94c for 60m

// Final extension / signal stabilisation: 98 C 10 min.
heat ddpcrLoaded at 98c for 10m

// Detect protein copy number (FAM channel; positive droplet count).
proteinSignal = detect ddPCRProteinDetection on ddpcrLoaded for 30s

// ============================================================
// BB2 / BB3: Protein detection QC gate
// Pass (BB2): proteinSignal > 0 -> protein count above LOD
//             (LOD: TNFR1=2277; CD147=2795; CSTB=18824 molecules);
//             dispose ddPCR droplets, continue to mRNA branch.
// Fail (BB3): proteinSignal <= 0 -> below LOD (e.g. HEK293T
//             TNFR1 cells all below LOD, consistent with paper
//             finding that TNFR1 is not expressed in HEK293T);
//             drain all droplets.
// Both branches converge at BB4 (proteinJoin).
// ============================================================

if (proteinSignal > 0) {
    dispose ddpcrLoaded
} else {
    drain ddpcrLoaded
}

// ============================================================
// BB4: proteinJoin
// Dispose protein QC signal. Control falls into the duplex
// mRNA/protein quantification branch (BB5/BB6).
// ============================================================

dispose proteinSignal

// ------------------------------------------------------------
// STEP 9: Duplex protein/mRNA quantification (same single cell).
//   Instead of splitting the lysate, one-step RT-ddPCR is
//   integrated with u-dPLA in the same ddPCR droplets.
//   RNaseOUT (20x dilution in all reagent mixes) protects mRNA
//   throughout PLA steps. After product retrieval, 9 uL PLA
//   products + mRNA are mixed with:
//     5 uL one-step RT-ddPCR Supermix
//     2 uL reverse transcriptase
//     1 uL 300 mM DTT
//     1 uL 20x Universal PCR Assay (FAM; PLA/protein readout)
//     1 uL 20x TaqMan TNFR1 probe (VIC; mRNA readout)
//     1 uL nuclease-free water
//   Total: 20 uL. Same droplet generation as Step 8.
//   FAM channel -> protein (PLA ligation products).
//   VIC channel -> mRNA (RT-ddPCR amplicons from TNFR1 mRNA).
//   Cross-talk validation: VIC/FAM crosstalk negligible
//   (Supplementary Fig. 5a/b). N=38 cells; Spearman rho=0.45.
//   RT program: 42 C 1h; 95 C 10 min; 40x (95 C 30s/60 C 1 min);
//   98 C 10 min; ramp 2 C/s.
//   1 h RT step = 60 min.
// ------------------------------------------------------------

// Retrieve combined PLA+mRNA products (same protocol as Step 8).
rnaseOut1    = dispense 1 units of RNaseOUT

// RNaseOUT added to all reagent mixes (20x dilution modelled
// as direct mix with products before RT-ddPCR assembly).
protectedRNA = mix plaProducts with rnaseOut1 for 1s

// Assemble duplex RT-ddPCR reaction mix.
rtSupermix   = dispense 1 units of RTddPCR_Supermix
revTranscrip = dispense 1 units of ReversTranscriptase
dttSolution  = dispense 1 units of DTT
univPCR2     = dispense 1 units of UniversalPCRAssay
tnfr1Probe   = dispense 1 units of TaqMan_TNFR1_Probe
dropletOil2  = dispense 1 units of DropletGenerationOil

duplexRxn1   = mix protectedRNA with rtSupermix for 5s
duplexRxn2   = mix duplexRxn1 with revTranscrip for 5s
duplexRxn3   = mix duplexRxn2 with dttSolution for 5s
duplexRxn4   = mix duplexRxn3 with univPCR2 for 5s
duplexRxn5   = mix duplexRxn4 with tnfr1Probe for 5s
duplexLoaded = mix duplexRxn5 with dropletOil2 for 5s

// RT step: 42 C for 1 h (= 60 min) to reverse transcribe mRNA.
heat duplexLoaded at 42c for 60m

// Activation: 95 C for 10 min.
heat duplexLoaded at 95c for 10m

// 40 amplification cycles: 95 C 30s + 60 C 1 min = 90s each.
// 40 cycles x 90s = 3600s = 60m.
heat duplexLoaded at 95c for 60m

// Final extension / signal stabilisation: 98 C 10 min.
heat duplexLoaded at 98c for 10m

// Detect mRNA (VIC channel; RT-ddPCR amplicons from TNFR1 mRNA).
mrnaSignal   = detect rtDdPCRmRNADetection on duplexLoaded for 30s

// ============================================================
// BB5 / BB6: mRNA detection QC gate
// Pass (BB5): mrnaSignal > 0 -> TNFR1 mRNA detected above LOD;
//             dispose duplex ddPCR droplets.
//             Paper result: Spearman rho=0.45 (N=38 H1299 cells),
//             significantly higher than previous ~0.1 estimates,
//             demonstrating that including lowly-expressing cells
//             (below previous dPLA LOD) raises mRNA-protein
//             correlation. (Fig. 3d/e)
// Fail (BB6): mrnaSignal <= 0 -> mRNA below detection; drain.
// Both branches converge at BB7 (mrnaJoin).
// ============================================================

if (mrnaSignal > 0) {
    dispose duplexLoaded
} else {
    drain duplexLoaded
}

// ============================================================
// BB7: mrnaJoin
// Dispose mRNA QC signal. Control falls into the HSV-1 viral
// infection profiling branch (BB8/BB9).
// ============================================================

dispose mrnaSignal

// ------------------------------------------------------------
// STEP 10: HSV-1 viral infection heterogeneity assay.
//   A549 human lung epithelial cells infected with HSV-1
//   expressing ICP4-YFP reporter (MOI 2; overnight).
//   Cells harvested, loaded on chip alongside control cells
//   (no virus). Loaded at 5 psi; chip moved to ice post-loading.
//
//   Live-cell time-lapse imaging (fluorescence) performed
//   on-chip before lysis to identify infected (ICP4-YFP+,
//   nuclear YFP signal) vs uninfected/control (YFP-) cells.
//   YFP images acquired; total fluorescence per cell calculated
//   by Matlab (imfindcircles + Rolling Ball Background
//   Subtraction in ImageJ).
//
//   After imaging, all cells lysed simultaneously with 0.3x
//   TM buffer (same lysis protocol as Steps 5-7).
//
//   HSV-1 PLA probes: polyclonal anti-HSV-1 antibody (ab9533,
//   Abcam) conjugated in-house via DBCO-NHS click chemistry.
//   Detects ~80 HSV-1 viral protein species.
//
//   Key finding (Fig. 4d): Spearman rho=0.48 between ICP4-YFP
//   fluorescence and total viral protein count, indicating
//   that not all HSV-1-infected cells (YFP+) progress past
//   the immediate-early protein synthesis stage; some undergo
//   abortive infection. Wide single-cell distribution:
//   highest expressors show ~5x more viral protein than lowest.
// ------------------------------------------------------------

// Dispense HSV-1 infected A549 cell and control (no virus) cell.
infectedCell = dispense 1 units of HSV1_InfectedCell
ctrlCell     = dispense 1 units of ControlCell
pbsTrap2     = dispense 1 units of PBS
pbsTrap3     = dispense 1 units of PBS

// Hydrodynamic trapping (Chamber II) of infected and control cells.
trappedInfected = mix infectedCell with pbsTrap2 for 2s
trappedControl  = mix ctrlCell with pbsTrap3 for 2s

// Live-cell fluorescence imaging before lysis.
// liveCellImagingDetection: abstracts on-chip time-lapse YFP
// imaging. ICP4-YFP signal (nuclear) classifies infected cells.
// Uninfected and control cells show no YFP signal.
infectionSignal = detect liveCellImagingDetection on trappedInfected for 10m

// Lysis of all cells simultaneously (0.3x TM buffer, on ice).
lysisBuffer2     = dispense 1 units of LysisBuffer
viralLysate      = mix trappedInfected with lysisBuffer2 for 10m
heat viralLysate at 0c for 10m

// HSV-1 PLA probes incubation (Chamber III/IV, 37 C, 1 h = 60 min).
plaProbeHSV  = dispense 1 units of PLAProbes
viralProbeIncub = mix viralLysate with plaProbeHSV for 60m
heat viralProbeIncub at 37c for 60m

// Ligation (Chamber V): ice 30 min, 37 C 10 min, 65 C 5 min.
ligMixViral  = dispense 1 units of LigationMix
viralLigMix  = mix viralProbeIncub with ligMixViral for 30m
heat viralLigMix at 0c for 30m
heat viralLigMix at 37c for 10m
heat viralLigMix at 65c for 5m

// Retrieve viral PLA products for ddPCR.
waterFlush4   = dispense 1 units of MilliQWater
viralProducts = mix viralLigMix with waterFlush4 for 2m

ddpcrMix2    = dispense 1 units of ddPCR_Supermix
universalPCR2 = dispense 1 units of UniversalPCRAssay
dropletOil3  = dispense 1 units of DropletGenerationOil

viralRxn1    = mix viralProducts with ddpcrMix2 for 5s
viralRxn2    = mix viralRxn1 with universalPCR2 for 5s
viralLoaded  = mix viralRxn2 with dropletOil3 for 5s

// ddPCR thermal cycling (same program as Step 8).
heat viralLoaded at 95c for 10m
heat viralLoaded at 94c for 60m
heat viralLoaded at 98c for 10m

// Detect viral protein count (FAM channel; positive droplet count).
// viralProteinDetection: abstracts ddPCR readout of HSV-1 PLA
// products, correlated with ICP4-YFP (infectionSignal) per cell.
viralProteinReadout = detect viralProteinDetection on viralLoaded for 30s

// ============================================================
// BB8 / BB9: Viral infection profiling QC gate
// Pass (BB8): infectionSignal > 0 -> ICP4-YFP+ cell confirmed
//             infected (nuclear entry occurred); dispose viral
//             protein readout droplets. Partial correlation
//             (rho=0.48) between YFP level and total viral protein
//             count suggests a sub-population undergoes abortive
//             infection after immediate-early gene expression.
//             (Fig. 4c: p=5.356e-11, two-sided Welch's t test,
//             N=27 infected vs N=19 control cells)
// Fail (BB9): infectionSignal <= 0 -> cell is uninfected (YFP-)
//             or control (no virus); drain viral protein droplets.
// Both branches converge at BB10 (finalCleanup).
// ============================================================

if (infectionSignal > 0) {
    dispose viralLoaded
} else {
    drain viralLoaded
}

// ============================================================
// BB10: finalCleanup (terminal)
// Dispose all remaining QC signal droplets.
// Experiment ends.
// ============================================================

dispose infectionSignal
dispose viralProteinReadout
dispose stdProducts

// [terminal -- no further instructions; exit node for CFG]

// Digital microfluidic blood-plasma separation + 21-step RV IgG chemiluminescent
// ELISA, adapted from Dixon, Lamanna & Wheeler, Lab Chip, 2020, 20, 1845-1855.
//
// Note: the BioScript compiler's built-in detection modules do not include a
// "chemiluminescence" sensor, so this protocol is declared under the
// "fluorescence" module (as in the ciprofloxacin/probabilistic_pcr reference
// scripts) and used to model the luminometer readout from the paper's PMT
// (steps 19-21).
module fluorescence

manifest whole_blood
manifest extraction_buffer
manifest virus_particles
manifest wash_buffer
manifest conjugate_solution
manifest luminol_enhancer
manifest stable_h2o2

instructions:

// --- Steps 1-4: on-chip blood-plasma separation (extraction zone) ---
// Five-unit extraction-buffer droplet dispensed onto the array (~6.5 uL)
buffer = dispense 5 units of extraction_buffer
// Whole blood "dabbed" onto the plasma separation membrane (~55 uL)
blood = dispense 55 units of whole_blood
// Blood wicks through the membrane onto the extraction droplet (~3 min)
loaded = mix blood with buffer for 180s
// Extraction droplet driven through the transport membrane (~30 s)
plasma = mix loaded with buffer for 30s
dispose loaded

// --- Step 5: virus-coated paramagnetic particles delivered to assay zone ---
particles = dispense 2 units of virus_particles

// --- Step 6: separated plasma mixed with particles, actively mixed 7 min ---
complex = mix plasma with particles for 420s

// --- Steps 7-12: wash cycle (initial wash + 5 repeats), 30 s each ---
repeat 6 times {
    wash = dispense 2 units of wash_buffer
    complex = mix complex with wash for 30s
    dispose wash
}

// --- Step 13: HRP-conjugated anti-human IgG delivered, mixed 5 min ---
conjugate = dispense 2 units of conjugate_solution
complex = mix complex with conjugate for 300s

// --- Steps 14-17: wash cycle repeated 4 times, 30 s each ---
repeat 4 times {
    wash = dispense 2 units of wash_buffer
    complex = mix complex with wash for 30s
    dispose wash
}

// --- Step 18: final wash before moving to detection zone, 10 s ---
wash = dispense 2 units of wash_buffer
complex = mix complex with wash for 10s
dispose wash

// --- Step 19: luminol enhancer solution delivered, mixed 10 s ---
luminol = dispense 1 units of luminol_enhancer
complex = mix complex with luminol for 10s

// --- Step 20: stable H2O2 substrate delivered, mixed 80 s ---
h2o2 = dispense 1 units of stable_h2o2
complex = mix complex with h2o2 for 80s

// --- Step 21: chemiluminescence measured for 120 s ---
rv_igg_signal = detect fluorescence on complex for 120s

// WHO diagnostic cut-off for RV immunity is 10 IU/mL
if (rv_igg_signal < 10) {
    // sample reads non-immune
    dispose complex
}
if (rv_igg_signal >= 10) {
    // sample reads immune
    dispose complex
}

module bacterialMargination
module yeastMargination
module cellularComponentDetection
module bacterialColonyCount

manifest WholeBlood
manifest PBS
manifest BSA_Buffer
manifest Dextran40
manifest GFP_Ecoli
manifest YFP_Saccharomyces
manifest CD41a_FITC
manifest CD45_APC
manifest LB_Agar

// ============================================================
// A Microfluidics Approach Towards High-Throughput Pathogen
// Removal from Blood Using Margination
// Hou, Gan, Bhagat, Li, Lim, Han
// Biomicrofluidics 6, 024115 (2012)
// DOI: 10.1063/1.4710992
//
// Platform: Pressure-driven continuous-flow PDMS microfluidic
// device. Two cascaded straight margination channels (20 x 20 um,
// W x H) with bifurcations (1:8:1) in series. No digital
// microfluidics. All dispense operations represent sample or
// reagent introduction from syringe pump inlets.
//
// Separation Principle: Whole blood flows through 20 x 20 um
// microchannels at 15 uL/min (Re ~4-5). Deformable RBCs
// migrate axially to the channel centre (Fahreaus effect),
// forming an RBC-rich core and a cell-free layer at the walls.
// Mechanical RBC-cell collisions drive margination of bacteria,
// yeast, platelets, and leukocytes into the wall-adjacent
// cell-free layer. At the bifurcation (1:8:1), marginated
// cells exit via the narrow side channels (waste) while
// RBC-enriched blood exits via the large centre outlet
// (filtered blood). Two cascaded stages achieve >80% bacterial
// removal efficiency in a single pass.
//
// BioScript Abstractions:
//   - `mix` models continuous laminar co-flow through the
//     margination channel (NOT DMF electrode mixing). The
//     mixing duration encodes channel transit time at the
//     working flow rate.
//   - `heat at 25c` models ambient-temperature incubation
//     steps (antibody staining, room-temperature operations).
//   - `heat at 4c` models on-ice or cold incubation.
//   - `heat at 37c` models bacterial culture incubation.
//   - `drain` is used for waste-stream side outlet collection
//     (marginated cell fraction). `dispose` is used for
//     confirmed filtered centre outlet fractions.
//   - Centrifugation (RBC washing) is abstracted as
//     `heat at 25c` since no centrifuge primitive exists.
//   - The 1:8:1 bifurcation geometry and cell-free-layer
//     enhancement at the expanded outlet are encoded
//     implicitly in the two-stage mix/detect structure.
//   - The parallel 6-channel device (100 uL/min total)
//     is encoded as a separate branch in the QC-pass path,
//     sharing the same reagent manifests.
//
// CFG STRUCTURE:
//   BB1  main               -- sample prep; antibody staining;
//                              two-stage margination; FACS QC gate
//   BB2  separationPass     -- separationSignal > 0: high removal
//                              efficiency confirmed; proceed to
//                              bacterial quantification
//   BB3  separationFail     -- separationSignal <= 0: insufficient
//                              removal; drain filtered fraction
//   BB4  separationJoin     -- join: bacterial CFU counting branch
//   BB5  bacteriaPass       -- bacteriaSignal > 0: >80% removal
//                              confirmed by CFU; dispose
//   BB6  bacteriaFail       -- bacteriaSignal <= 0: low removal;
//                              drain and flag for re-run
//   BB7  finalCleanup       -- terminal: dispose all QC signals
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: Prepare washed RBC sample at physiological hematocrit.
//   Human whole blood washed 3x with PBS + 0.5% BSA to remove
//   plasma proteins. Final RBC concentration adjusted to 45%
//   hematocrit in sample buffer: PBS + 0.5% BSA + 3% Dextran-40
//   (Dextran-40 prevents cell sedimentation during pump-driven
//   flow). This step is required for device characterisation
//   experiments; for whole-blood pathogen removal experiments,
//   unwashed fresh blood is used directly (see STEP 3).
//   Centrifugation abstracted as heat at 25c (no centrifuge
//   primitive in BioScript).
// ------------------------------------------------------------

bloodSample   = dispense 1 units of WholeBlood
washBuffer1   = dispense 1 units of PBS

// First wash: centrifuge 300 x g, 5 min, remove supernatant.
washedBlood1  = mix bloodSample with washBuffer1 for 5m
heat washedBlood1 at 25c for 5m

washBuffer2   = dispense 1 units of PBS
washedBlood2  = mix washedBlood1 with washBuffer2 for 5m
heat washedBlood2 at 25c for 5m

washBuffer3   = dispense 1 units of PBS
washedBlood3  = mix washedBlood2 with washBuffer3 for 5m
heat washedBlood3 at 25c for 5m

// Resuspend at 45% hematocrit in sample buffer.
bsaBuffer     = dispense 1 units of BSA_Buffer
dextranBuffer = dispense 1 units of Dextran40
sampleBuffer  = mix bsaBuffer with dextranBuffer for 30s

rbcSuspension = mix washedBlood3 with sampleBuffer for 30s

// ------------------------------------------------------------
// STEP 2: Antibody staining for whole-blood cellular analysis.
//   Fresh whole blood (unwashed, not the washed RBC sample) is
//   incubated at 4c for 40 min with:
//     CD41a-FITC (1:50, BD Biosciences) -- platelet marker
//     CD45-APC  (1:100, BD Biosciences) -- leukocyte marker
//   Staining done directly in blood without prior washing to
//   preserve native platelet and leukocyte populations.
// ------------------------------------------------------------

freshBlood    = dispense 1 units of WholeBlood
cd41a         = dispense 1 units of CD41a_FITC
cd45          = dispense 1 units of CD45_APC

antibodyMix   = mix cd41a with cd45 for 30s
stainedBlood  = mix freshBlood with antibodyMix for 2m
heat stainedBlood at 4c for 40m

// ------------------------------------------------------------
// STEP 3: Spike whole blood with GFP-E. coli and YFP-S. cerevisiae.
//   GFP-E. coli (HB101 K-12, cultured overnight at 37c in
//   LB Agar + ampicillin 100 ug/mL + arabinose 0.1%) spiked
//   at 1e6-1e7 CFU/mL. YFP-S. cerevisiae (W303-1B) spiked at
//   same concentration range. Both microbes vortexed 30 s into
//   blood immediately before device loading.
//   NOTE: E. coli (rod, ~2 x 0.5 um) and S. cerevisiae
//   (ovoid, ~5 um) are similar in size to platelets (~2-3 um)
//   and to Candida albicans (pathogenic fungal model),
//   respectively. Size difference from RBCs drives margination.
// ------------------------------------------------------------

ecoliGFP      = dispense 1 units of GFP_Ecoli
saccharomyces = dispense 1 units of YFP_Saccharomyces

// Vortex microbes into stained blood sample (30 s).
microbeBlood1 = mix stainedBlood with ecoliGFP for 30s
spikedBlood   = mix microbeBlood1 with saccharomyces for 30s

// ------------------------------------------------------------
// STEP 4: Load spiked blood into the margination device.
//   Syringe pump delivers whole blood at 15 uL/min into the
//   device inlet. Working flow rate selected to maximise
//   bacteria margination efficiency while staying within
//   device pressure tolerance (PDMS + tubing connection).
//   Re ~4-5. Wall shear rate ~6e4 s-1 (inhibits RBC
//   aggregation; Fahreaus-dominated margination regime).
//
//   Channel geometry:
//     First margination channel: 20 x 20 um (W x H), 5 mm long
//     Cascaded channel: 20 x 20 um (W x H), 1 mm long
//     Bifurcations: 1:8:1 (side:centre:side outlet ratio)
//     Aspect ratio = 1 (optimal for isotropic shear and
//     RBC core formation across the full cross-section).
//
//   `mix` models laminar co-flow through the margination
//   channel. Duration encodes transit time at 15 uL/min.
//   `rbcSuspension` supplies the RBC hydrodynamic environment
//   required for margination physics; spikedBlood carries
//   the pathogen and inflammatory cell cargo.
// ------------------------------------------------------------

// First-stage margination channel (5 mm, 15 uL/min).
// RBCs migrate axially; bacteria, yeast, platelets, and
// leukocytes marginate radially to the four channel walls.
stage1Mix     = mix spikedBlood with rbcSuspension for 20s

// Bifurcation 1 (1:8:1): marginated cells exit side channels
// (waste stream); RBC-enriched blood exits centre outlet.
// Side outlet collection: drain models waste stream removal.
stage1Waste   = mix stage1Mix with rbcSuspension for 5s
drain stage1Waste

// Centre outlet after stage 1: bacteria-depleted blood
// (approx. 50% bacterial removal, hematocrit +~10%).
stage1Filtered = mix stage1Mix with rbcSuspension for 10s

// ------------------------------------------------------------
// STEP 5: Second-stage margination (cascaded design).
//   The bacteria-depleted blood from stage 1 enters the
//   second margination channel (1 mm). Higher hematocrit
//   post-stage-1 enhances Fahreaus effect and RBC-bacteria
//   hydrodynamic interactions, driving additional bacterial
//   margination to the channel periphery.
//   Cumulative two-stage removal efficiency: >80% bacteria.
//   Platelets and leukocytes: >80% depletion.
//   RBC concentration at centre outlet: +~30% above inlet
//   (Fahreaus effect; 1:8:1 bifurcation concentrates RBCs).
//   Negligible haemolysis confirmed by optical absorption
//   at 414 nm (RBC transit time <0.01 s in shear zone).
// ------------------------------------------------------------

// Second-stage margination channel (1 mm, 15 uL/min).
stage2Mix     = mix stage1Filtered with rbcSuspension for 5s

// Bifurcation 2 (1:8:1): second margination waste stream.
stage2Waste   = mix stage2Mix with rbcSuspension for 2s
drain stage2Waste

// Final filtered blood at centre outlet after stage 2.
// Contains: RBC-enriched blood with >80% bacteria removed,
// >80% platelets removed, >80% leukocytes removed,
// ~90% S. cerevisiae removed (larger size -> corner
// margination -> complete sidewall capture).
filteredBlood = mix stage2Mix with rbcSuspension for 5s

// ------------------------------------------------------------
// STEP 6: FACS analysis of filtered blood at centre outlet.
//   BD LSR II flow cytometer. Cell populations gated by
//   forward scatter (FSC), side scatter (SSC), and
//   fluorescence channels:
//     CD41a-FITC: platelet gate
//     CD45-APC:   leukocyte gate
//     GFP:        E. coli gate
//     YFP:        S. cerevisiae gate
//   Normalised concentration = (cells at outlet) / (inlet)
//   for each population. QC threshold: >80% removal for
//   bacteria, platelets, and leukocytes; >80% RBC recovery.
//   FACS detection abstracted via cellularComponentDetection
//   module (covers all four fluorescence channels simultaneously).
// ------------------------------------------------------------

separationSignal = detect cellularComponentDetection on filteredBlood for 30s

// ============================================================
// BB2 / BB3: FACS QC gate
// Pass (BB2): separationSignal > 0 -> >80% removal of
//             inflammatory and pathogenic components confirmed;
//             proceed to CFU bacterial quantification.
// Fail (BB3): separationSignal <= 0 -> removal efficiency
//             below threshold; drain filtered fraction and
//             flag device for geometric re-optimisation.
// Both branches converge at BB4 (separationJoin).
// ============================================================

if (separationSignal > 0) {
    dispose filteredBlood
} else {
    drain filteredBlood
}

// ============================================================
// BB4: separationJoin
// Dispose FACS QC signal. Control falls into bacterial
// CFU quantification branch (BB5/BB6).
// ============================================================

dispose separationSignal

// ------------------------------------------------------------
// STEP 7: Bacterial CFU quantification at inlet and outlet.
//   10 uL aliquots from inlet (spiked blood) and filtered
//   centre outlet are plated on LB agar. Colony-forming units
//   (CFUs) counted after 24 h incubation at 37c. Removal
//   efficiency = 1 - (CFU_outlet / CFU_inlet).
//   Haemocytometer used independently for yeast concentration.
//   Expected results:
//     E. coli removal: ~80% (two-stage cascaded device)
//     S. cerevisiae removal: ~90% (larger size, corner
//     margination to all four channel walls)
//   `heat at 37c for 1440m` models 24 h agar plate incubation
//   (1440 min = 24 h converted per compiler duration constraint).
// ------------------------------------------------------------

agarPlate       = dispense 1 units of LB_Agar
filteredAliquot = dispense 1 units of WholeBlood

platesMix       = mix filteredAliquot with agarPlate for 30s
heat platesMix at 37c for 1440m

bacteriaSignal  = detect bacterialColonyCount on platesMix for 30s

// ============================================================
// BB5 / BB6: Bacterial CFU QC gate
// Pass (BB5): bacteriaSignal > 0 -> >80% bacterial removal
//             confirmed by CFU count; dispose all. Device
//             validated for sepsis treatment application.
//             Multiplexed 6-channel parallel system (100 uL/min
//             total; 6 ml/h) achieves similar filtration
//             performance at 6x throughput.
// Fail (BB6): bacteriaSignal <= 0 -> CFU count indicates
//             insufficient removal; drain and re-optimise
//             flow rate or channel geometry.
// Both branches converge at BB7 (finalCleanup).
// ============================================================

if (bacteriaSignal > 0) {
    dispose platesMix
} else {
    drain platesMix
}

// ============================================================
// BB7: finalCleanup (terminal)
// Dispose CFU QC signal. Experiment ends.
// ============================================================

dispose bacteriaSignal

// [terminal -- no further instructions; exit node for CFG]

module nfkbTranslocationDetection
module geneExpressionDetection
module cellViabilityDetection

manifest TNFalpha
manifest IL1beta
manifest LPS
manifest PAM2CSK4
manifest PBS
manifest CompleteMedia
manifest PluronicF127
manifest FluorescentNFkBCells
manifest FDA_PI_Stain

instructions:

// ============================================================
// Processing Stimulus Dynamics by the NF-kB Network in
// Single Cells.
// Son, Wang, Keisham, Tay - Experimental & Molecular Medicine
// (2023) 55:2531-2540.
// DOI: 10.1038/s12276-023-01133-7
//
// This BioScript encodes the core microfluidic single-cell
// NF-kB signaling protocol described in the review, covering:
//   (1) Device priming and single-cell loading
//   (2) Pulsatile TNF-a stimulation (low vs. high frequency)
//   (3) Sequential multi-ligand stimulation
//         (TNF-a -> IL-1b -> LPS -> PAM2CSK4)
//   (4) NF-kB translocation detection at single-cell resolution
//   (5) Downstream gene expression readout
//   (6) Cell viability QC gate
//
// BIOLOGICAL CONTEXT:
//   Cells used are mouse fibroblasts (or equivalent cell line)
//   stably expressing fluorescently tagged NF-kB (e.g. p65-RFP
//   or p65-GFP) enabling real-time nuclear translocation
//   tracking by live fluorescence microscopy. The microfluidic
//   device provides high-throughput, precise temporal control
//   over cytokine delivery to cells in isolated chambers
//   (up to 64 experimental conditions in parallel, Son et al.
//   Sci. Signal. 2021).
//
// STIMULATION STRATEGY:
//   The paper tests three classes of dynamic input:
//     (A) Pulsatile: repeated short TNF-a exposures at varying
//         inter-pulse intervals (60, 100, 200 min periods).
//     (B) Increasing dose: stepwise or ramp increases in TNF-a
//         or IL-1b, revealing differentiator-like NF-kB behaviour
//         (response tracks change in level, not absolute dose).
//     (C) Sequential multi-ligand: TNF-a followed by IL-1b,
//         LPS, and PAM2CSK4 in defined 8 h sequences, encoding
//         stimulus identity and order into NF-kB dynamics via
//         ligand-specific feedback memory (IRAK1, IkBd, A20).
//
// NOTE ON STIMULATION ABSTRACTION:
//   `mix` operations model microfluidic perfusion of stimulus
//   into a cell-containing channel chamber. They do not
//   represent DMF electrode mixing. Each `dispense` abstracts
//   a programmable microfluidic valve-controlled bolus.
//   Duration arguments to `mix` encode the perfusion window
//   (i.e. the pulse duration or the incubation period).
//
// NOTE ON TIME UNITS:
//   BioScript supports `s` (seconds) and `m` (minutes) only.
//   All durations are expressed in `m` or `s` accordingly.
//   Inter-pulse recovery periods (e.g. 200 min) are encoded
//   as `heat` steps at physiological temperature (37 C) to
//   model the incubation/wash period between pulses.
//
// CFG STRUCTURE:
//   BB1  main                -- entry: priming, cell loading,
//                               pulsatile stimulation arm,
//                               NF-kB translocation detection
//   BB2  nfkbPass            -- nfkbSignal > 0: oscillatory
//                               NF-kB response confirmed;
//                               proceed to sequential stimulation
//   BB3  nfkbFail            -- nfkbSignal <= 0: no translocation
//                               detected; drain cells
//   BB4  nfkbJoin            -- join: sequential ligand arm begins
//   BB5  seqPass             -- seqSignal > 0: sequence-encoded
//                               NF-kB dynamics confirmed;
//                               proceed to gene expression readout
//   BB6  seqFail             -- seqSignal <= 0: no sequence
//                               encoding detected; drain
//   BB7  seqJoin             -- join: gene expression & viability
//   BB8  expressionPass      -- expressionSignal > 0: target gene
//                               upregulation confirmed; dispose
//   BB9  expressionFail      -- expressionSignal <= 0: no
//                               expression; drain
//   BB10 finalCleanup        -- terminal: dispose all QC signals
// ============================================================

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: Prime microfluidic device.
//   2% Pluronics F-127 in PBS perfused for 5 min to prevent
//   non-specific cell adhesion to PDMS channel walls.
//   Consistent with standard microfluidic cell culture setup
//   (Son et al. Biosens. Bioelectron. 2023; Samlali et al.
//   Small 2020).
// ------------------------------------------------------------

primingPBS      = dispense 1 units of PBS
primingPluronic = dispense 1 units of PluronicF127
primingMix      = mix primingPBS with primingPluronic for 5m

// ------------------------------------------------------------
// STEP 2: Load fluorescently tagged NF-kB reporter cells.
//   Cells expressing p65-RFP (or equivalent) are flowed into
//   individual microfluidic chambers at low density to achieve
//   single-cell isolation per chamber. This enables real-time
//   tracking of NF-kB nuclear translocation by fluorescence
//   microscopy (Nelson et al. J. Cell Sci. 2002; Tay et al.
//   Nature 2010).
//   NOTE: `mix` abstracts channel-based cell loading; no
//   reagent mixing in the DMF sense occurs at this step.
// ------------------------------------------------------------

reporterCells   = dispense 1 units of FluorescentNFkBCells
loadedCells     = mix reporterCells with primingMix for 2m

// ------------------------------------------------------------
// STEP 3: Equilibration.
//   Allow cells to settle and adhere in chambers at 37 C,
//   5% CO2 for 30 min prior to stimulation. Ensures baseline
//   NF-kB is cytoplasmic before stimulus delivery.
// ------------------------------------------------------------

heat loadedCells at 37c for 30m

// ============================================================
// PULSATILE STIMULATION ARM (Pulse 1 of 3)
// Low-frequency pulsatile TNF-a (200 min inter-pulse period).
// From Ashall et al. Science 2009 and Kellogg & Tay Cell 2015.
// Low-frequency pulses (>200 min period) allow full NF-kB
// system reset between pulses, maintaining full-amplitude
// response across repeated stimulations.
//
// Protocol: 15 min TNF-a pulse -> 185 min wash/recovery ->
//           repeat x3. 15-min pulses at ~10 ng/mL TNF-a.
// ============================================================

// ------------------------------------------------------------
// STEP 4: Pulsatile TNF-a - Pulse 1.
//   Deliver TNF-a (10 ng/mL) for 15 min via programmable
//   valve. Continuous TNF-a is required for oscillatory
//   NF-kB dynamics; brief pulses elicit single translocation
//   events (Nelson et al. Science 2004; Turner et al.
//   J. Cell Sci. 2010).
// ------------------------------------------------------------

tnfPulse1       = dispense 1 units of TNFalpha
stimulation1    = mix loadedCells with tnfPulse1 for 15m

// ------------------------------------------------------------
// STEP 5: Inter-pulse wash and recovery (Pulse 1 -> Pulse 2).
//   Replace TNF-a with PBS to terminate stimulation.
//   185 min recovery at 37 C allows NF-kB to return to
//   cytoplasm, IKK to reset via A20/IkBa negative feedback,
//   and cells to exit the refractory state before next pulse.
//   Total inter-pulse period = 185 + 15 = 200 min.
// ------------------------------------------------------------

washPBS1        = dispense 1 units of PBS
washedCells1    = mix stimulation1 with washPBS1 for 5m
heat washedCells1 at 37c for 185m

// ------------------------------------------------------------
// STEP 6: Pulsatile TNF-a - Pulse 2.
//   Second 15 min TNF-a pulse. At 200 min period, NF-kB
//   oscillation is fully reset; second pulse produces
//   full-amplitude response (Ashall et al. Science 2009).
// ------------------------------------------------------------

tnfPulse2       = dispense 1 units of TNFalpha
stimulation2    = mix washedCells1 with tnfPulse2 for 15m

washPBS2        = dispense 1 units of PBS
washedCells2    = mix stimulation2 with washPBS2 for 5m
heat washedCells2 at 37c for 185m

// ------------------------------------------------------------
// STEP 7: Pulsatile TNF-a - Pulse 3.
//   Third 15 min TNF-a pulse. Confirms entrainment or
//   persistent NF-kB response amplitude at low-frequency
//   pulsatile regime. Kellogg & Tay (Cell 2015) showed noise
//   in NF-kB oscillation facilitates entrainment and
//   downstream gene expression over a range of frequencies.
// ------------------------------------------------------------

tnfPulse3       = dispense 1 units of TNFalpha
stimulation3    = mix washedCells2 with tnfPulse3 for 15m

washPBS3        = dispense 1 units of PBS
washedCells3    = mix stimulation3 with washPBS3 for 5m

// ------------------------------------------------------------
// STEP 8: NF-kB translocation detection (pulsatile arm).
//   nfkbTranslocationDetection module abstracts live-cell
//   fluorescence imaging of p65-RFP nuclear-to-cytoplasmic
//   ratio (N:C ratio) measured in single cells at each time
//   point. Translocation confirmed by N:C ratio > 1 at peak.
//   Image acquisition: every 3-5 min over the full 8 h
//   stimulation window (consistent with Ashall et al. and
//   Kellogg & Tay protocols).
//   Detection window: 90 s per chamber scan.
// ------------------------------------------------------------

nfkbSignal      = detect nfkbTranslocationDetection on washedCells3 for 90s

// ============================================================
// BB2 / BB3: NF-kB translocation QC gate (pulsatile arm)
// Pass (BB2): nfkbSignal > 0 -> oscillatory NF-kB translocation
//             confirmed across all three pulses; proceed to
//             sequential ligand stimulation arm (BB4).
// Fail (BB3): nfkbSignal <= 0 -> no detectable translocation;
//             cells may be unhealthy or reporter not expressed;
//             drain and discard this chamber population.
// Both branches converge at BB4 (nfkbJoin).
// ============================================================

if (nfkbSignal > 0) {
    dispose washedCells3
} else {
    drain washedCells3
}

// ============================================================
// BB4: nfkbJoin
// Dispose pulsatile arm NF-kB signal. Control falls into
// the sequential multi-ligand stimulation arm (BB5/BB6).
// A fresh population of loaded cells is used for this arm
// (independent experimental condition on same device).
// ============================================================

dispose nfkbSignal

// ============================================================
// SEQUENTIAL MULTI-LIGAND STIMULATION ARM
// From Wang, Son et al. Cell Rep. 2022 (ref 15 in paper).
// Four-ligand sequence over 8 h: TNF-a -> IL-1b -> LPS -> PAM.
// Each ligand delivered for ~2 h (120 min) then washed off.
// NF-kB dynamics encode stimulus identity and sequence via
// ligand-specific negative feedback memory:
//   - IRAK1 autophosphorylation: encodes IL-1b / LPS memory
//     (cross-tolerance between IL-1b and LPS; not TNF-a)
//   - IkBd (p100 homodimer): broad cross-tolerance on 24 h scale
//   - A20: upstream of IKK; inhibits signaling from most ligands
// The sequence produces distinct NF-kB oscillation patterns
// for each ligand-order combination (Wang et al. Cell Rep. 2022).
// ============================================================

// ------------------------------------------------------------
// STEP 9: Load fresh reporter cells for sequential arm.
//   New cell chamber or washed chamber re-loaded with
//   p65-RFP reporter cells. Same priming and equilibration
//   as Steps 1-3.
//   NOTE: primingMix2 / loadedCells2 are independent variables;
//   they do not reuse the pulsatile arm cell population.
// ------------------------------------------------------------

primingPBS2     = dispense 1 units of PBS
primingPluronic2 = dispense 1 units of PluronicF127
primingMix2     = mix primingPBS2 with primingPluronic2 for 5m

reporterCells2  = dispense 1 units of FluorescentNFkBCells
loadedCells2    = mix reporterCells2 with primingMix2 for 2m
heat loadedCells2 at 37c for 30m

// ------------------------------------------------------------
// STEP 10: Sequential stimulus 1 - TNF-a (0-120 min).
//   TNF-a (10 ng/mL) delivered for 120 min.
//   TNF-a signals via TNFR -> TRADD/RIP1/TRAF2/5 -> TAK1 -> IKK.
//   Does NOT activate IRAK1/MyD88 myddosome pathway.
//   Primary NF-kB response: damped oscillation, 1-3 peaks.
//   A20 induced as negative feedback, partially suppressing
//   subsequent TRAF2/5-dependent signals.
// ------------------------------------------------------------

tnfSeq          = dispense 1 units of TNFalpha
seqStim1        = mix loadedCells2 with tnfSeq for 120m

washSeq1        = dispense 1 units of PBS
seqWashed1      = mix seqStim1 with washSeq1 for 5m

// ------------------------------------------------------------
// STEP 11: Sequential stimulus 2 - IL-1b (120-240 min).
//   IL-1b (10 ng/mL) delivered for 120 min beginning at t=120m.
//   IL-1b signals via IL-1R -> MyD88/IRAK1/TRAF6 (myddosome).
//   After prior TNF-a, A20 levels are elevated. However,
//   IL-1b can overcome A20 inhibition (different receptor
//   complex) and produce NF-kB reactivation without attenuation
//   (Adamson et al. Nat. Commun. 2016; DeFelice et al.
//   Sci. Signal. 2019 - ref 64 in paper).
//   IRAK1 begins to autophosphorylate, encoding IL-1b memory.
// ------------------------------------------------------------

il1bSeq         = dispense 1 units of IL1beta
seqStim2        = mix seqWashed1 with il1bSeq for 120m

washSeq2        = dispense 1 units of PBS
seqWashed2      = mix seqStim2 with washSeq2 for 5m

// ------------------------------------------------------------
// STEP 12: Sequential stimulus 3 - LPS (240-360 min).
//   LPS (100 ng/mL) delivered for 120 min beginning at t=240m.
//   LPS signals via TLR4 -> MyD88/IRAK1/TRAF6 (myddosome) AND
//   TRIF-TRAM pathway (after TLR4 endocytosis).
//   LPS and IL-1b share the IRAK1/MyD88 myddosome. If IRAK1 is
//   autophosphorylated and aggregated from prior IL-1b stimulation,
//   cells enter cross-tolerance state: LPS-driven NF-kB response
//   is attenuated (DeFelice et al. Sci. Signal. 2019 - ref 64).
//   Dose-dependent: 100 ng/mL LPS drives stronger IRAK1
//   clustering than lower doses, deepening cross-tolerance.
// ------------------------------------------------------------

lpsSeq          = dispense 1 units of LPS
seqStim3        = mix seqWashed2 with lpsSeq for 120m

washSeq3        = dispense 1 units of PBS
seqWashed3      = mix seqStim3 with washSeq3 for 5m

// ------------------------------------------------------------
// STEP 13: Sequential stimulus 4 - PAM2CSK4 (360-480 min).
//   PAM2CSK4 (100 ng/mL) delivered for 120 min (t=360-480m).
//   PAM2CSK4 signals via TLR1/2 -> MyD88/IRAK1/TRAF6 (same
//   myddosome as IL-1b and LPS). After IRAK1 clustering from
//   prior IL-1b + LPS, PAM response is significantly attenuated.
//   Son et al. (Sci. Signal. 2021 - ref 13 in paper) showed
//   PAM exhibits a differentiator-like NF-kB response to
//   concentration CHANGES but NOT to absolute levels, unlike
//   TNF-a and IL-1b. Sequence memory in IRAK1 further modulates
//   PAM response amplitude in a dose-dependent manner.
//   Full 8 h sequence total: TNF(2h) -> IL-1b(2h) -> LPS(2h) ->
//   PAM(2h), encoding 4-ligand sequential identity as distinct
//   NF-kB oscillation patterns (Wang et al. Cell Rep. 2022).
// ------------------------------------------------------------

pamSeq          = dispense 1 units of PAM2CSK4
seqStim4        = mix seqWashed3 with pamSeq for 120m

washSeq4        = dispense 1 units of PBS
seqWashed4      = mix seqStim4 with washSeq4 for 5m

// ------------------------------------------------------------
// STEP 14: NF-kB translocation detection (sequential arm).
//   Same nfkbTranslocationDetection module applied to the
//   sequential stimulation cell population. Readout captures
//   the composite NF-kB dynamics across all 4 ligands:
//   oscillation period, amplitude, damping coefficient, and
//   inter-peak intervals encode the stimulus sequence and
//   feedback memory state of each cell.
//   Detection window: 90 s per chamber (consistent with Step 8).
// ------------------------------------------------------------

seqSignal       = detect nfkbTranslocationDetection on seqWashed4 for 90s

// ============================================================
// BB5 / BB6: Sequential stimulation NF-kB QC gate
// Pass (BB5): seqSignal > 0 -> sequence-encoded NF-kB dynamics
//             detected; distinct oscillation patterns for each
//             ligand confirmed; proceed to gene expression arm.
// Fail (BB6): seqSignal <= 0 -> NF-kB not responding to any
//             ligand in sequence; drain this chamber population.
// Both branches converge at BB7 (seqJoin).
// ============================================================

if (seqSignal > 0) {
    dispose seqWashed4
} else {
    drain seqWashed4
}

// ============================================================
// BB7: seqJoin
// Dispose sequential arm NF-kB signal. Control falls into
// the downstream gene expression and viability QC arm
// (BB8/BB9).
// ============================================================

dispose seqSignal

// ============================================================
// DOWNSTREAM GENE EXPRESSION AND CELL VIABILITY ARM
// The paper demonstrates that distinct NF-kB oscillation
// dynamics (amplitude, duration, period) produce distinct
// transcriptional outputs. Lane et al. (Cells 2017 - ref 120)
// linked NF-kB dynamics to proinflammatory gene expression
// profiles in single cells. Cheng et al. (Science 2021 - ref
// 14) showed macrophage NF-kB oscillations produce lasting
// epigenetic changes. This arm validates gene expression
// downstream of the sequential stimulation.
//
// Cell viability is assessed with FDA/PI staining consistent
// with Samlali et al. (Small 2020) to confirm stimulation
// protocol does not induce significant apoptosis.
// ============================================================

// ------------------------------------------------------------
// STEP 15: Downstream gene expression readout.
//   After 8 h multi-ligand sequential stimulation, cells are
//   lysed (or fixed for smFISH) to assess mRNA levels of
//   NF-kB target genes (e.g. IL-6, CXCL8/IL-8, IkBa, A20,
//   TNF-a). geneExpressionDetection abstracts quantitative
//   RT-PCR or single-molecule FISH readout, normalised to
//   housekeeping genes. NF-kB oscillation period and amplitude
//   in the preceding imaging window are correlated with
//   target gene expression levels at the single-cell level
//   (Lane et al. Cells 2017; Wang et al. Cell Rep. 2022).
//   Detection window: 30 min for lysis + qPCR abstraction.
// ------------------------------------------------------------

expressCells    = dispense 1 units of FluorescentNFkBCells
expressMedia    = dispense 1 units of CompleteMedia
expressMix      = mix expressCells with expressMedia for 5m

expressionSignal = detect geneExpressionDetection on expressMix for 30m

// ============================================================
// BB8 / BB9: Gene expression QC gate
// Pass (BB8): expressionSignal > 0 -> NF-kB target gene
//             upregulation confirmed (IL-6, CXCL8, IkBa
//             elevated above baseline); dispose cells.
// Fail (BB9): expressionSignal <= 0 -> no detectable gene
//             expression response; cells may be refractory
//             or dead; drain.
// Both branches converge at BB10 (finalCleanup).
// ============================================================

if (expressionSignal > 0) {
    // --------------------------------------------------------
    // Cell viability QC (pass path only):
    //   FDA (live, green) and PI (dead, red) staining to
    //   confirm >80% viability across the 8 h stimulation.
    //   Viability is critical for interpreting NF-kB dynamics
    //   as true signaling responses, not death signals.
    //   (Son et al. Sci. Signal. 2021 - ref 13)
    //   Incubate stain for 10 min at room temperature.
    // --------------------------------------------------------
    fdaPiStain      = dispense 1 units of FDA_PI_Stain
    stainedCells    = mix expressMix with fdaPiStain for 10m

    viabilitySignal = detect cellViabilityDetection on stainedCells for 30s

    dispose stainedCells
    dispose viabilitySignal
    dispose expressMix
} else {
    drain expressMix
}

// ============================================================
// BB10: finalCleanup (terminal)
// Dispose all remaining QC signal droplets.
// Experiment ends. NF-kB stimulus dynamics protocol complete.
// ============================================================

dispose expressionSignal

// [terminal -- no further instructions; exit node for CFG]

module nimsLaserDetection
module nimsFluorescenceDetection
module nimsIonDetection

manifest BoronSilicon
manifest HydrofluoricAcid_Ethanol
manifest PerfluorinatedSiloxane_Initiator
manifest Nitrogen_Gas
manifest BSA_TrypticDigest
manifest Verapamil
manifest Bradykinin_1_7
manifest Bradykinin_2_9
manifest Neurotensin
manifest MCF7_Cells_MDA_MB231
manifest FDA_PI_Stain
manifest MouseEmbryoTissueSection
manifest FreshBlood
manifest FreshUrine
manifest AcetonitrileWater_01TFA

// ============================================================
// Clathrate Nanostructures for Mass Spectrometry
// Northen, Yanes, Northen, Marrinucci, Uritboonthai,
// Apon, Golledge, Nordstrom, Siuzdak -- Nature 2007, 449,
// 1033-1036. DOI: 10.1038/nature06195
//
// Protocol: Nanostructure-Initiator Mass Spectrometry (NIMS).
// The NIMS surface (nanostructured porous silicon, ~10-nm pores)
// traps perfluorinated siloxane initiator molecules within
// clathrate-like pores. Laser or ion irradiation vaporises
// the initiator, triggering desorption and ionisation of
// surface-adsorbed analytes without a conventional MALDI matrix.
//
// This BioScript file encodes the four primary application
// demonstrations from the paper in sequence:
//   (A) BSA tryptic digest and small molecule detection
//       (verapamil, 1-palmitoyllysophosphatidylcholine) -- Fig 1d
//   (B) Single cancer cell metabolite profiling (MDA-MB-231) -- Fig 2
//   (C) Peptide microarray characterisation (ion-NIMS, Bi3+) -- Fig 3
//   (D) Tissue imaging (mouse embryo, laser-NIMS) -- Fig 4
//   (E) Direct biofluid analysis (blood and urine) -- Fig 5
//
// NOTE ON NIMS SURFACE FABRICATION:
//   The NIMS chip itself is fabricated off-chip by anodic etching
//   of low-resistivity P-type <100> silicon (0.01-0.02 Ohm.cm) at
//   48 mA.cm^-2 in 25% HF/ethanol for 30 min, followed by initiator
//   loading and nitrogen-jet removal of excess. The `mix` steps in
//   SECTION I abstract this surface preparation sequence as a DMF
//   analogue. All subsequent analyte deposition steps represent
//   direct spotting (0.5 uL drops) or robotic contact printing
//   (1.4 nL drops) onto the prepared NIMS surface.
//
// NOTE ON DETECTOR MODULES:
//   nimsLaserDetection  -- abstracts VoyagerDE STR MALDI-TOF
//                          (337 nm N2 laser, reflector mode,
//                          +20 kV, 100-shot average)
//   nimsFluorescenceDetection -- abstracts Nikon TE2000
//                          epi-fluorescence with DAPI/FITC/TRITC
//                          filter sets (FDA/PI viability readout)
//   nimsIonDetection    -- abstracts ION-TOF IV TOF-SIMS with
//                          Bi3+ primary ion source (25 kV, 45deg
//                          angle, 50 ns pulse, <static dose limit)
//
// NOTE ON DURATION ENCODING:
//   BioScript duration tokens are `s` and `m` only.
//   30 min anodic etch = 30m; 30-60 min initiator loading = 45m
//   (midpoint); 100-shot laser average modelled as 30s detect.
//
// CFG STRUCTURE:
//   BB1  main               -- entry: NIMS surface prep
//   BB2  surfacePrepPass    -- surfaceQC > 0: surface ready,
//                             proceed to analyte studies
//   BB3  surfacePrepFail    -- surfaceQC <= 0: etch failed, drain
//   BB4  surfacePrepJoin    -- join: analyte deposition begins
//   BB5  peptideAssayPass   -- peptideSignal > 0: BSA digest
//                             detected (>55% sequence coverage),
//                             dispose
//   BB6  peptideAssayFail   -- peptideSignal <= 0: no signal, drain
//   BB7  peptideAssayJoin   -- join: single-cell branch begins
//   BB8  cellAssayPass      -- cellSignal > 0: phospholipid
//                             ions from single cell detected,
//                             dispose
//   BB9  cellAssayFail      -- cellSignal <= 0: no cell signal,
//                             drain
//   BB10 cellAssayJoin      -- join: microarray branch begins
//   BB11 arrayAssayPass     -- arraySignal > 0: peptide array
//                             ions detected at 1 fmol, dispose
//   BB12 arrayAssayFail     -- arraySignal <= 0: no array signal,
//                             drain
//   BB13 arrayAssayJoin     -- join: tissue imaging branch begins
//   BB14 tissueImagingPass  -- tissueSignal > 0: lipid ion
//                             images acquired, dispose
//   BB15 tissueImagingFail  -- tissueSignal <= 0: no tissue
//                             signal, drain
//   BB16 tissueImagingJoin  -- join: biofluid branch begins
//   BB17 biofluidPass       -- biofluidSignal > 0: blood/urine
//                             metabolites detected, dispose
//   BB18 biofluidFail       -- biofluidSignal <= 0: no biofluid
//                             signal, drain
//   BB19 finalCleanup       -- terminal: dispose all QC signals
// ============================================================

instructions:

// ============================================================
// BB1: main
// SECTION I: NIMS SURFACE FABRICATION
// ============================================================

// ------------------------------------------------------------
// STEP 1: Anodic etching of silicon to form nanostructured
//         porous silicon surface.
//         Material: P-type <100> boron-doped silicon wafer,
//         resistivity 0.01-0.02 Ohm.cm, 525 +/- 25 um thick,
//         100 mm diameter (Silicon Valley Microelectronics).
//         Etchant: 25% hydrofluoric acid in ethanol.
//         Current density: 48 mA.cm^-2, duration: 30 min.
//         Result: ~10-nm pore nanostructured silicon surface
//         (confirmed by SEM, Fig 1c). CAUTION: HF is acutely
//         hazardous; all handling under certified fume hood
//         with appropriate PPE and neutralising agent on hand.
//         `heat` at 25c models room-temperature anodic etch.
// ------------------------------------------------------------

siliconWafer  = dispense 1 units of BoronSilicon
etchSolution  = dispense 1 units of HydrofluoricAcid_Ethanol

// Anodic etch: 48 mA.cm^-2 for 30 min at ambient temperature.
// `mix` abstracts the electrochemical etching of the wafer
// surface by the HF/ethanol solution under applied current.
etchedSurface = mix siliconWafer with etchSolution for 30m
heat etchedSurface at 25c for 30m

// ------------------------------------------------------------
// STEP 2: Initiator loading.
//         Undiluted bis(tridecafluoro-1,1,2,2-tetrahydrooctyl)
//         tetramethyldisiloxane applied to etched surface at
//         25degC for 30-60 min (45 min modelled here).
//         Initiator molecules migrate into the pores under
//         capillary forces and adopt a highly ordered clathrate-
//         like arrangement (confirmed by Supplementary Movie 1:
//         reversible migration on slight heating/cooling).
//         Excess initiator removed with nitrogen jet.
//         This step is the same for silanized and unsilanized
//         surfaces (Supplementary Information).
// ------------------------------------------------------------

initiator    = dispense 1 units of PerfluorinatedSiloxane_Initiator
nitrogenJet  = dispense 1 units of Nitrogen_Gas

// Load initiator: 45 min incubation at 25degC.
loadedSurface = mix etchedSurface with initiator for 45m
heat loadedSurface at 25c for 45m

// Nitrogen-jet removal of excess surface initiator.
nimsSurface   = mix loadedSurface with nitrogenJet for 30s

// ------------------------------------------------------------
// STEP 3: NIMS surface QC.
//         nimsLaserDetection module abstracts a test laser shot
//         to verify that the surface produces initiator-derived
//         background ions under 337 nm irradiation, confirming
//         successful pore filling before analyte deposition.
// ------------------------------------------------------------

surfaceQC = detect nimsLaserDetection on nimsSurface for 10s

// ============================================================
// BB2 / BB3: Surface preparation QC gate
// Pass (BB2): surfaceQC > 0 -> initiator signal confirmed;
//             proceed to analyte characterisation sections.
// Fail (BB3): surfaceQC <= 0 -> etching or loading failed;
//             drain and repeat surface preparation.
// Both branches converge at BB4 (surfacePrepJoin).
// ============================================================

if (surfaceQC > 0) {
    dispose nimsSurface
} else {
    drain nimsSurface
}

// ============================================================
// BB4: surfacePrepJoin
// Dispose surface QC signal. Begin analyte deposition studies.
// ============================================================

dispose surfaceQC

// ============================================================
// SECTION II: LASER-NIMS -- PEPTIDE AND SMALL MOLECULE DETECTION
// Corresponds to Figure 1d (paper).
// Laser: 337 nm pulsed N2 (Voyager DE STR, Applied Biosystems).
// Initiator: bis(tridecafluoro-1,1,2,2-tetrahydrooctyl)
//            tetramethyldisiloxane, undiluted.
// Drop volume: 0.5 uL per spot (contact spotting).
// Acquisition: reflector mode, +20 kV, 100-shot average,
//              first grid 60%, guide wire 0.15%, delay 100 ns.
// ============================================================

// ------------------------------------------------------------
// STEP 4: BSA tryptic digest detection.
//         BSA reduced (DTT), alkylated (iodoacetamide), then
//         digested with mass-spec-grade porcine trypsin (Promega).
//         500 amol of BSA tryptic digest spotted in 0.5 uL
//         onto NIMS surface; solvent evaporated before analysis.
//         Expected result: 55% sequence coverage (Fig 1d,
//         upper right panel). Analyte in AcN/water/0.1% TFA.
// ------------------------------------------------------------

bsaDigest     = dispense 1 units of BSA_TrypticDigest
bsaSolvent    = dispense 1 units of AcetonitrileWater_01TFA

// Prepare BSA tryptic digest spot: mix analyte in solvent.
// `mix` abstracts robotic or manual 0.5 uL drop deposition.
bsaSpot       = mix bsaDigest with bsaSolvent for 10s

// Evaporate solvent at room temperature (25degC, 5 min) before
// laser irradiation. Modelled as a 25degC heat step.
heat bsaSpot at 25c for 5m

// Laser-NIMS analysis: 337 nm, 100 shots averaged.
bsaSpot_nims  = mix bsaSpot with nimsSurface for 5s
peptideSignal = detect nimsLaserDetection on bsaSpot_nims for 30s

// ------------------------------------------------------------
// STEP 5: Small molecule detection -- verapamil (700 ymol).
//         Calcium antagonist drug; molecular weight 454.6 Da.
//         700 ymol = 7e-22 mol. Lowest amount demonstrated
//         in Fig 1d (lower left panel). Spotted in 0.5 uL.
//         NOTE: 1 ymol (yoctomole) = 1e-24 mol; the paper
//         reports 700 ymol = 7e-22 mol, which equates to
//         approximately 420 molecules on the surface. This
//         represents the extreme sensitivity limit of NIMS
//         versus MALDI (typically 1 fmol range).
// ------------------------------------------------------------

verapamilDrop = dispense 1 units of Verapamil
verapamilSpot = mix verapamilDrop with nimsSurface for 5s
heat verapamilSpot at 25c for 5m

// ============================================================
// BB5 / BB6: Peptide/small molecule assay QC gate
// Pass (BB5): peptideSignal > 0 -> BSA digest detected at
//             500 amol (>55% coverage); dispose spots.
// Fail (BB6): peptideSignal <= 0 -> no signal; drain spots.
// Both branches converge at BB7 (peptideAssayJoin).
// ============================================================

if (peptideSignal > 0) {
    dispose bsaSpot_nims
    dispose verapamilSpot
} else {
    drain bsaSpot_nims
    drain verapamilSpot
}

// ============================================================
// BB7: peptideAssayJoin
// Dispose peptide QC signal. Begin single-cell branch.
// ============================================================

dispose peptideSignal

// ============================================================
// SECTION III: SINGLE-CELL METABOLITE PROFILING BY LASER-NIMS
// Corresponds to Figure 2 (paper).
// Cell line: MDA-MB-231 (highly metastatic breast cancer,
//            ATCC HTB-26). Grown in Leibovitz's L-15 medium
//            + 2 mM L-glutamine + 10% calf bovine serum at
//            37degC. Harvested by trypsin-EDTA treatment.
// Deposition: micromanipulator (MINJ-PD; Tritech Research)
//             used to deposit single cells directly onto NIMS.
// Initiator: bis(tridecafluoro-1,1,2,2-tetrahydrooctyl)
//            tetramethyldisiloxane calibrated with Na+, K+,
//            phosphocholine, 1-palmitoyllysophosphatidylcholine.
// Detection: phospholipids (endogenous), m/z 400-900 range.
//            Superior spectral complexity vs hundreds of cells
//            measured by nanoESI, MALDI, or ion-NIMS (Fig 2c).
// Post-MS: cells fixed (2% paraformaldehyde), permeabilised
//          (cold methanol), immunofluorescently stained with
//          DAPI + Alexa555-anti-Pan-cytokeratin.
// ============================================================

// ------------------------------------------------------------
// STEP 6: Deposit single MDA-MB-231 cell onto NIMS surface.
//         Micromanipulator precisely counts and deposits a
//         single cell; cell dried before MS analysis.
//         `mix` abstracts cell deposition and drying step.
// ------------------------------------------------------------

singleCell      = dispense 1 units of MCF7_Cells_MDA_MB231
cellOnSurface   = mix singleCell with nimsSurface for 2s
heat cellOnSurface at 25c for 5m

// ------------------------------------------------------------
// STEP 7: Laser-NIMS acquisition on single cell.
//         337 nm irradiation identifies the cell location
//         (green fluorescent box, same laser at high intensity
//         -- Fig 2a). Lower-energy pulses then profile the
//         cell's phospholipid content. 100-shot average.
// ------------------------------------------------------------

cellSignal = detect nimsLaserDetection on cellOnSurface for 30s

// ------------------------------------------------------------
// STEP 8: Post-MS viability / immunofluorescence staining.
//         FDA/PI stain for live/dead assessment; DAPI nuclear
//         counterstain; Alexa555-cytokeratin for cell identity.
//         nimsFluo module abstracts Nikon TE2000 acquisition
//         with 20x Plan Fluor (NA 0.45) and 60x oil Plan Apo
//         (NA 1.40) objectives, Retiga EXi camera.
// ------------------------------------------------------------

fdaPiStain      = dispense 1 units of FDA_PI_Stain
stainedCell     = mix cellOnSurface with fdaPiStain for 10m

fluoroSignal = detect nimsFluorescenceDetection on stainedCell for 30s

// ============================================================
// BB8 / BB9: Single-cell MS QC gate
// Pass (BB8): cellSignal > 0 -> endogenous phospholipids
//             detected from single cell; dispose.
// Fail (BB9): cellSignal <= 0 -> no cell signal; drain.
// Both branches converge at BB10 (cellAssayJoin).
// ============================================================

if (cellSignal > 0) {
    dispose stainedCell
    dispose fluoroSignal
} else {
    drain stainedCell
    drain fluoroSignal
}

// ============================================================
// BB10: cellAssayJoin
// Dispose cell QC signal. Begin peptide microarray branch.
// ============================================================

dispose cellSignal

// ============================================================
// SECTION IV: ION-NIMS PEPTIDE MICROARRAY CHARACTERISATION
// Corresponds to Figure 3 (paper).
// Ion source: ION-TOF IV TOF-SIMS with Bi3+ primary ions.
//             25 kV beam energy, 45deg angle, 50 ns pulse width,
//             primary ion dose below static limit.
//             Secondary ions directed to TOF tube at +/-2.5 kV
//             (sample at +2.5 kV, extraction lens at -4.5 kV).
// Lateral resolution: ~150 nm ion beam (Fig 3c inset).
// Peptides printed: bradykinin 2-9 (904 Da, red),
//                  neurotensin (1673 Da, blue),
//                  bradykinin 1-7 (757 Da, yellow) at 1 fmol.
// Printing: custom arrayer, ArrayIt contact printing head,
//           1.4 nL drops, 1:1 AcN/water + 0.1% TFA solution.
// Sensitivity: 1 fmol per peptide -- 1000x improvement over
//              conventional TOF-SIMS strategies (Ref 16, 21).
// Ion-NIMS surface: 14-kDa poly(3,3,3-trifluoropropylmethyl-
//   siloxanes) on silanized/vacuum-baked silicon, baked 100degC
//   overnight; excess removed with N2 jet + tBME rinse.
// ============================================================

// ------------------------------------------------------------
// STEP 9: Print peptide array spots onto ion-NIMS surface.
//         Three peptide species deposited by robotic contact
//         printing (1.4 nL drops) from 1:1 AcN/water + 0.1%
//         TFA. `mix` abstracts robotic array printing.
// ------------------------------------------------------------

bk27_solution   = dispense 1 units of Bradykinin_2_9
bk17_solution   = dispense 1 units of Bradykinin_1_7
nt_solution     = dispense 1 units of Neurotensin
arraySolvent    = dispense 1 units of AcetonitrileWater_01TFA

// Mix each peptide in solvent (1:1 AcN/water, 0.1% TFA).
bk27_spot       = mix bk27_solution with arraySolvent for 5s
bk17_spot       = mix bk17_solution with arraySolvent for 5s
nt_spot         = mix nt_solution with arraySolvent for 5s

// Print array onto ion-NIMS surface via robotic contact printing.
peptideArray    = mix bk27_spot with nimsSurface for 5s
peptideArray    = mix bk17_spot with peptideArray for 5s
peptideArray    = mix nt_spot with peptideArray for 5s

// Dry printed array at 25degC before Bi3+ ion analysis.
heat peptideArray at 25c for 5m

// ------------------------------------------------------------
// STEP 10: Ion-NIMS Bi3+ imaging.
//          nimsIonDetection abstracts TOF-SIMS acquisition:
//          selective ion images for m/z 904 (BK 2-9, red),
//          m/z 1673 (neurotensin, blue), m/z 757 (BK 1-7,
//          yellow). High-resolution image with 150-nm beam
//          shows localisation at centre of printed spot
//          (Fig 3c). BK 1-7 on silicon control shows
//          significant fragmentation vs NIMS (Fig 3d).
// ------------------------------------------------------------

arraySignal = detect nimsIonDetection on peptideArray for 30s

// ============================================================
// BB11 / BB12: Peptide microarray QC gate
// Pass (BB11): arraySignal > 0 -> all three peptides detected
//              at 1 fmol with spatial localisation; dispose.
// Fail (BB12): arraySignal <= 0 -> ion imaging failed; drain.
// Both branches converge at BB13 (arrayAssayJoin).
// ============================================================

if (arraySignal > 0) {
    dispose peptideArray
} else {
    drain peptideArray
}

// ============================================================
// BB13: arrayAssayJoin
// Dispose array QC signal. Begin tissue imaging branch.
// ============================================================

dispose arraySignal

// ============================================================
// SECTION V: TISSUE IMAGING BY LASER-NIMS
// Corresponds to Figure 4 (paper).
// Sample: Mouse embryo, C57Bl/6J, embryonic day 16.5.
//         Embryos frozen in OCT compound on dry ice, equilibrated
//         to -20degC, cryosectioned at 12 um thickness
//         (Leica CM3050 S), thaw-mounted onto NIMS chip.
// Initiator: bis(heptadecafluoro-1,1,2,2-tetrahydrodecyl)
//            tetramethyldisiloxane.
// Imaging: 20-um step size, ~15-um diameter laser beam.
//          Two-step protocol:
//   (i)  Laser etching: 0.4 J.cm^-2 per pulse to ablate tissue
//        and expose underlying NIMS surface.
//   (ii) NIMS imaging: 0.01 J.cm^-2 per pulse to desorb/ionise
//        metabolites at the tissue/NIMS interface.
// Target lipids: glycerophosphatidylcholine (m/z 782, arrow,
//   Fig 4b) localised around developing vertebra. Also
//   phosphatidylethanolamine (via post-source decay fragment ions).
// Result: 300-um-wide false-colour mass intensity image shows
//   higher lipid signal (red/yellow/cyan) surrounding the
//   developing vertebra (dark blue). Scale bar: 1 mm.
// ============================================================

// ------------------------------------------------------------
// STEP 11: Tissue section preparation and mounting.
//          12-um cryosections thaw-mounted directly onto
//          NIMS chip. `mix` abstracts the thaw-mount step.
// ------------------------------------------------------------

tissueSection   = dispense 1 units of MouseEmbryoTissueSection
mountedTissue   = mix tissueSection with nimsSurface for 30s

// ------------------------------------------------------------
// STEP 12: Laser etching (ablation) phase.
//          High-energy laser pulses (0.4 J.cm^-2, 337 nm)
//          ablate the 12-um tissue slice to expose the
//          underlying NIMS surface at the tissue interface.
//          `heat` at 25degC abstracts the photothermal ablation
//          step (pulsed laser; no bulk heating intended).
// ------------------------------------------------------------

heat mountedTissue at 25c for 2m

// ------------------------------------------------------------
// STEP 13: NIMS metabolite imaging (low-energy irradiation).
//          Low-energy pulses (0.01 J.cm^-2, 337 nm) interrogate
//          the tissue/NIMS interface; initiator vaporisation
//          desorbs metabolites from the etched surface.
//          100-shot average per raster point; 20-um steps.
//          nimsLaserDetection abstracts the spatially resolved
//          mass spectral acquisition across the tissue section.
// ------------------------------------------------------------

tissueSignal = detect nimsLaserDetection on mountedTissue for 30s

// ============================================================
// BB14 / BB15: Tissue imaging QC gate
// Pass (BB14): tissueSignal > 0 -> lipid ion images (m/z 782,
//              GPC) acquired with anatomical contrast; dispose.
// Fail (BB15): tissueSignal <= 0 -> no tissue MS signal; drain.
// Both branches converge at BB16 (tissueImagingJoin).
// ============================================================

if (tissueSignal > 0) {
    dispose mountedTissue
} else {
    drain mountedTissue
}

// ============================================================
// BB16: tissueImagingJoin
// Dispose tissue QC signal. Begin direct biofluid branch.
// ============================================================

dispose tissueSignal

// ============================================================
// SECTION VI: DIRECT BIOFLUID ANALYSIS BY LASER-NIMS
// Corresponds to Figure 5 (paper).
// Samples: 1 uL fresh human blood and 1 uL fresh urine spotted
//          directly onto NIMS without any sample preparation.
//          After 30 s, droplets blown off with nitrogen stream.
// Blood:   Laser-etched first (0.4 J.cm^-2, ~0.5 s) to ablate
//          cellular material, then NIMS analysis of surface layer.
//          Initiator: bis(heptadecafluoro-1,1,2,2-tetrahydrodecyl)
//          tetramethyldisiloxane (perfluorinated, lipid-selective).
//          Dominant ions: phospholipids (e.g. PC lipids).
// Urine:   Spotted directly, no etch step. Two initiators tested:
//          (a) bis(heptadecafluoro...) -- lipid-selective, blue spectrum
//          (b) 1,3-bis(hydroxybutyl)tetramethyldisiloxane
//              (polar hydroxylated) -- small metabolites, green spectrum.
//          ~86% of ions from (b) unique to polar initiator surface.
// Quantitation: Codeine spiked into urine at multiple concentrations.
//          Linear NIMS response up to 15 ng.mL^-1 (Fig 5 inset).
//          Limit of detection <15 ng.mL^-1 vs 75-250 ng.mL^-1
//          for conventional bioanalytical approaches (Ref 28).
// ============================================================

// ------------------------------------------------------------
// STEP 14: Blood analysis -- direct spot + laser etch.
//          1 uL fresh blood spotted, held 30 s, then excess
//          blown off with nitrogen. Laser-etch step ablates
//          red blood cell matrix before NIMS interrogation.
// ------------------------------------------------------------

bloodSample     = dispense 1 units of FreshBlood
nitrogenBlowOff = dispense 1 units of Nitrogen_Gas

bloodOnSurface  = mix bloodSample with nimsSurface for 30s
bloodExcess     = mix bloodOnSurface with nitrogenBlowOff for 5s

// Laser etch at high energy to ablate cellular blood components.
heat bloodExcess at 25c for 1m

// NIMS analysis of the laser-etched blood surface interface.
bloodNIMS       = mix bloodExcess with nimsSurface for 5s

// ------------------------------------------------------------
// STEP 15: Urine analysis -- direct spot, no etch.
//          1 uL fresh urine spotted directly onto NIMS; excess
//          blown off with N2. No laser-etch step for urine.
//          Urine spectra dominated by small metabolites <500 Da
//          (e.g. putative gangliosides GM2/GM1 also detected).
//          Spectra converted to ASCII, baseline-corrected,
//          normalised (TIC), and realigned in SpecAlign.
// ------------------------------------------------------------

urineSample     = dispense 1 units of FreshUrine
nitrogenBlowOff2 = dispense 1 units of Nitrogen_Gas

urineOnSurface  = mix urineSample with nimsSurface for 30s
urineExcess     = mix urineOnSurface with nitrogenBlowOff2 for 5s

urineNIMS       = mix urineExcess with nimsSurface for 5s

// ------------------------------------------------------------
// STEP 16: Laser-NIMS acquisition on blood and urine.
//          biofluidSignal keyed on blood (red spectrum, Fig 5).
//          Urine detection run in parallel.
// ------------------------------------------------------------

biofluidSignal  = detect nimsLaserDetection on bloodNIMS for 30s
urineSignal     = detect nimsLaserDetection on urineNIMS for 30s

// ============================================================
// BB17 / BB18: Biofluid analysis QC gate
// Pass (BB17): biofluidSignal > 0 -> blood phospholipids and
//              urine metabolites detected without background;
//              dispose all biofluid droplets.
// Fail (BB18): biofluidSignal <= 0 -> no biofluid signal
//              (initiator loading failure or spotting error);
//              drain all.
// Both branches converge at BB19 (finalCleanup).
// ============================================================

if (biofluidSignal > 0) {
    dispose bloodNIMS
    dispose urineNIMS
    dispose urineSignal
} else {
    drain bloodNIMS
    drain urineNIMS
    drain urineSignal
}

// ============================================================
// BB19: finalCleanup (terminal)
// Dispose all remaining QC signal droplets.
// Experiment ends.
// ============================================================

dispose biofluidSignal

// [terminal -- no further instructions; exit node for CFG]

module fluorescence

manifest methanolic_extract
manifest dpph_solution

instructions:

// Step 1: Combine 40 uL of methanolic extract with 160 uL of 100 uM DPPH solution (in methanol)
extract = dispense 40 units of methanolic_extract
dpph = dispense 160 units of dpph_solution
reaction = mix extract with dpph

// Step 2: Incubate in the dark at room temperature for 30 min
heat reaction at 25c for 30m

// Step 3: Measure absorbance at 517 nm to quantify DPPH radical scavenging activity
// (detect fluorescence used as the generic optical-signal readout stand-in, since BioScript
// exposes no dedicated absorbance/spectrophotometric detect module)
dpph_reading = detect fluorescence on reaction for 30s

dispose reaction

module fluorescenceAssay
module pixelCount

manifest HEPESBuffer
manifest GDPInhibitor
manifest FucTEnzyme
manifest GlycolysationMix
manifest HydrolysisMix
manifest GlycineSolution

instructions:

// ============================================================
// FUCOSYLTRANSFERASE INHIBITION ASSAY ON DIGITAL MICROFLUIDICS
// Leclerc et al., Biomicrofluidics 13, 034106 (2019)
// Inhibitor: GDP (guanosine 5'-diphosphate)
// Enzyme: H. pylori alpha(1,3)-fucosyltransferase (FucT)
// Substrate: MU-beta-LacNAc (4-methylumbelliferyl beta-N-acetyllactosaminide)
// Reporter: 4-MU fluorescence (lambda_ex = 365 nm, lambda_em = 460 nm)
// ============================================================

// ------------------------------------------------------------
// STEP 1: Prime HEPES buffer reservoirs (6 x ~2.7 uL each)
// Buffer: 25 mM pH 7.0 HEPES + 0.05% Pluronics F-68
// Each reservoir used as the diluent for one dilution step
// ------------------------------------------------------------

buffer1 = dispense 1 units of HEPESBuffer
buffer2 = dispense 1 units of HEPESBuffer
buffer3 = dispense 1 units of HEPESBuffer
buffer4 = dispense 1 units of HEPESBuffer
buffer5 = dispense 1 units of HEPESBuffer
buffer6 = dispense 1 units of HEPESBuffer

// ------------------------------------------------------------
// STEP 2: Load GDP inhibitor stock (80 mM) via pipetting inlet
// Covered with silicone oil shell via coated pipette tip
// Dispense one unit droplet (~500 nL) for first dilution step
// ------------------------------------------------------------

gdpUnit1 = dispense 1 units of GDPInhibitor

// ------------------------------------------------------------
// STEP 3: Serial ~5.5-fold dilution of GDP across 6 reservoirs
// Each mix merges a GDP unit droplet into the buffer reservoir
// producing the next lower concentration.
// Concentrations (by pixel count method):
//   gdpDrop1 ~36.0 mM
//   gdpDrop2 ~6.2 mM
//   gdpDrop3 ~1.1 mM
//   gdpDrop4 ~0.22 mM
//   gdpDrop5 ~0.04 mM
//   gdpDrop6 ~0.006 mM
//   gdpBlank  0.0 mM  (HEPES only, no inhibitor)
// NOTE: dispense only accepts manifest items; serial dilution
// is achieved purely through mix operations on variables.
// ------------------------------------------------------------

// Dilution 1: gdpUnit1 (~80 mM) mixed into buffer1 -> ~36 mM
gdpDrop1 = mix gdpUnit1 with buffer1 for 10s

// Dilution 2: gdpDrop1 mixed into buffer2 -> ~6.2 mM
gdpDrop2 = mix gdpDrop1 with buffer2 for 10s

// Dilution 3: gdpDrop2 mixed into buffer3 -> ~1.1 mM
gdpDrop3 = mix gdpDrop2 with buffer3 for 10s

// Dilution 4: gdpDrop3 mixed into buffer4 -> ~0.22 mM
gdpDrop4 = mix gdpDrop3 with buffer4 for 10s

// Dilution 5: gdpDrop4 mixed into buffer5 -> ~0.04 mM
gdpDrop5 = mix gdpDrop4 with buffer5 for 10s

// Dilution 6: gdpDrop5 mixed into buffer6 -> ~0.006 mM
gdpDrop6 = mix gdpDrop5 with buffer6 for 10s

// Blank: 0 mM GDP control (pure HEPES buffer, no inhibitor)
gdpBlank = dispense 1 units of HEPESBuffer

// ------------------------------------------------------------
// STEP 4: Dispense FucT enzyme unit droplets (~500 nL each)
// FucT: 0.03 mg/mL (0.6 nM) in 25 mM HEPES + 0.05% F-68
// One droplet per GDP concentration (6) + one for blank = 7 total
// All solutions surrounded by silicone oil shell
// ------------------------------------------------------------

fucT1 = dispense 1 units of FucTEnzyme
fucT2 = dispense 1 units of FucTEnzyme
fucT3 = dispense 1 units of FucTEnzyme
fucT4 = dispense 1 units of FucTEnzyme
fucT5 = dispense 1 units of FucTEnzyme
fucT6 = dispense 1 units of FucTEnzyme
fucT7 = dispense 1 units of FucTEnzyme

// ------------------------------------------------------------
// STEP 5: Merge FucT droplet with each GDP concentration
// Each merged droplet = ~1 uL reaction volume
// ------------------------------------------------------------

fucTgdp1 = mix gdpDrop1 with fucT1 for 5s
fucTgdp2 = mix gdpDrop2 with fucT2 for 5s
fucTgdp3 = mix gdpDrop3 with fucT3 for 5s
fucTgdp4 = mix gdpDrop4 with fucT4 for 5s
fucTgdp5 = mix gdpDrop5 with fucT5 for 5s
fucTgdp6 = mix gdpDrop6 with fucT6 for 5s
fucTgdp7 = mix gdpBlank  with fucT7 for 5s

// ------------------------------------------------------------
// STEP 6: Incubate FucT + GDP for 5 min at room temperature
// Allows competitive binding of GDP to FucT active site
// ------------------------------------------------------------

heat fucTgdp1 at 25c for 5m
heat fucTgdp2 at 25c for 5m
heat fucTgdp3 at 25c for 5m
heat fucTgdp4 at 25c for 5m
heat fucTgdp5 at 25c for 5m
heat fucTgdp6 at 25c for 5m
heat fucTgdp7 at 25c for 5m

// ------------------------------------------------------------
// STEP 7: Dispense glycosylation mix unit droplets (~500 nL)
// Mix: 10 mM MgCl2, 0.01 mM MU-beta-LacNAc, 0.02 mM GDP-fucose
// in 25 mM HEPES + 0.05% Pluronics F-68
// Initiates the fucosylation reaction
// ------------------------------------------------------------

glyco1 = dispense 1 units of GlycolysationMix
glyco2 = dispense 1 units of GlycolysationMix
glyco3 = dispense 1 units of GlycolysationMix
glyco4 = dispense 1 units of GlycolysationMix
glyco5 = dispense 1 units of GlycolysationMix
glyco6 = dispense 1 units of GlycolysationMix
glyco7 = dispense 1 units of GlycolysationMix

rxn1 = mix fucTgdp1 with glyco1 for 5s
rxn2 = mix fucTgdp2 with glyco2 for 5s
rxn3 = mix fucTgdp3 with glyco3 for 5s
rxn4 = mix fucTgdp4 with glyco4 for 5s
rxn5 = mix fucTgdp5 with glyco5 for 5s
rxn6 = mix fucTgdp6 with glyco6 for 5s
rxn7 = mix fucTgdp7 with glyco7 for 5s

// ------------------------------------------------------------
// STEP 8: Incubate glycosylation reaction for 10 min at RT
// FucT transfers fucose from GDP-fucose onto MU-beta-LacNAc
// If GDP inhibits FucT -> MU-beta-LacNAc remains unfucosylated
// ------------------------------------------------------------

heat rxn1 at 25c for 10m
heat rxn2 at 25c for 10m
heat rxn3 at 25c for 10m
heat rxn4 at 25c for 10m
heat rxn5 at 25c for 10m
heat rxn6 at 25c for 10m
heat rxn7 at 25c for 10m

// ------------------------------------------------------------
// STEP 9: Dispense hydrolysis mix unit droplets (~500 nL)
// Mix: 25 mM EDTA, 0.05 mM BgaA (beta-gal, S. pneumoniae),
//      0.05 mM SpHex (N-acetylhexosaminidase, S. plicatus)
//      in 25 mM HEPES + 0.05% Pluronics F-68
// BgaA + SpHex sequentially cleave unfucosylated MU-beta-LacNAc
// releasing fluorescent 4-methylumbelliferone (4-MU)
// Fucosylated substrate is NOT cleaved -> low/no fluorescence
// ------------------------------------------------------------

hyd1 = dispense 1 units of HydrolysisMix
hyd2 = dispense 1 units of HydrolysisMix
hyd3 = dispense 1 units of HydrolysisMix
hyd4 = dispense 1 units of HydrolysisMix
hyd5 = dispense 1 units of HydrolysisMix
hyd6 = dispense 1 units of HydrolysisMix
hyd7 = dispense 1 units of HydrolysisMix

stopped1 = mix rxn1 with hyd1 for 5s
stopped2 = mix rxn2 with hyd2 for 5s
stopped3 = mix rxn3 with hyd3 for 5s
stopped4 = mix rxn4 with hyd4 for 5s
stopped5 = mix rxn5 with hyd5 for 5s
stopped6 = mix rxn6 with hyd6 for 5s
stopped7 = mix rxn7 with hyd7 for 5s

// ------------------------------------------------------------
// STEP 10: Incubate hydrolysis reaction for 5 min at RT
// Glycoside hydrolases release 4-MU from unfucosylated substrate
// ------------------------------------------------------------

heat stopped1 at 25c for 5m
heat stopped2 at 25c for 5m
heat stopped3 at 25c for 5m
heat stopped4 at 25c for 5m
heat stopped5 at 25c for 5m
heat stopped6 at 25c for 5m
heat stopped7 at 25c for 5m

// ------------------------------------------------------------
// STEP 11: Glycine dilution (5-fold) to correct bell-shaped
// dose-response artefact caused by GDP quenching of 4-MU signal
// GlycineSolution: 1 M glycine, pH 10.4
// Each stopped droplet (~500 nL) is merged with 4 units of
// glycine solution to achieve the 5-fold dilution on-chip
// This restores the sigmoidal curve shape and improves
// reproducibility by reducing solution viscosity
// Expected IC50 post-glycine: 0.093 +/- 0.037 mM GDP (DMF)
// ------------------------------------------------------------

glycine1 = dispense 1 units of GlycineSolution
glycine2 = dispense 1 units of GlycineSolution
glycine3 = dispense 1 units of GlycineSolution
glycine4 = dispense 1 units of GlycineSolution
glycine5 = dispense 1 units of GlycineSolution
glycine6 = dispense 1 units of GlycineSolution
glycine7 = dispense 1 units of GlycineSolution

diluted1 = mix stopped1 with glycine1 for 5s
diluted2 = mix stopped2 with glycine2 for 5s
diluted3 = mix stopped3 with glycine3 for 5s
diluted4 = mix stopped4 with glycine4 for 5s
diluted5 = mix stopped5 with glycine5 for 5s
diluted6 = mix stopped6 with glycine6 for 5s
diluted7 = mix stopped7 with glycine7 for 5s

// ------------------------------------------------------------
// STEP 12: Detect 4-MU fluorescence on-device
// Device mounted to 384-well plate; scanned by plate reader
// lambda_ex = 365 nm, lambda_em = 460 nm; gain = 750; 40 flashes
// signal1 = highest GDP (~36 mM): FucT fully inhibited -> HIGH signal
// signal7 = blank (0 mM GDP): FucT fully active -> LOW signal
// IC50 fit: y = b + ((a-b) / (1 + (x/c)^d)) least squares
// ------------------------------------------------------------

signal1 = detect fluorescenceAssay on diluted1 for 30s
signal2 = detect fluorescenceAssay on diluted2 for 30s
signal3 = detect fluorescenceAssay on diluted3 for 30s
signal4 = detect fluorescenceAssay on diluted4 for 30s
signal5 = detect fluorescenceAssay on diluted5 for 30s
signal6 = detect fluorescenceAssay on diluted6 for 30s
signal7 = detect fluorescenceAssay on diluted7 for 30s

// ------------------------------------------------------------
// STEP 13: Pixel count volume verification
// Image-based droplet volume measurement to back-calculate
// inhibitor concentrations via C1V1 = C2V2
// Homogeneity of dispensed droplets: <3% CV
// PC vs. fluorescence deviation: <0.05%
// ------------------------------------------------------------

vol1 = detect pixelCount on diluted1 for 5s
vol2 = detect pixelCount on diluted2 for 5s
vol3 = detect pixelCount on diluted3 for 5s
vol4 = detect pixelCount on diluted4 for 5s
vol5 = detect pixelCount on diluted5 for 5s
vol6 = detect pixelCount on diluted6 for 5s
vol7 = detect pixelCount on diluted7 for 5s

// ------------------------------------------------------------
// STEP 14: Evaluate assay signal and clean up
// Threshold of 15000 RFU on signal1 is an assay quality-check
// heuristic (NOT a paper-derived value) confirming successful
// inhibition at the highest GDP concentration.
// Pass -> dispose droplets directly.
// Fail -> drain droplets instead (avoids double-cleanup of the
// same diluted1..6 droplets, which the original version did).
// ------------------------------------------------------------

if (signal1 >= 15000) {
    dispose diluted1
    dispose diluted2
    dispose diluted3
    dispose diluted4
    dispose diluted5
    dispose diluted6
    dispose diluted7
} else {
    drain diluted1
    drain diluted2
    drain diluted3
    drain diluted4
    drain diluted5
    drain diluted6
    drain diluted7
}

dispose signal1
dispose signal2
dispose signal3
dispose signal4
dispose signal5
dispose signal6
dispose signal7
dispose vol1
dispose vol2
dispose vol3
dispose vol4
dispose vol5
dispose vol6
dispose vol7

module transformationQC
module endoglucanaseDetection

manifest CompetentCells
manifest pFAB4876
manifest pSB1C3_RFP
manifest CaCl2_Stock
manifest LB_Media
manifest MUC_Substrate
manifest EndoglucanaseEnzyme
manifest QuenchingSolution
manifest Buffer
manifest PluronicF68

// ============================================================
// Integration of World-to-Chip Interfaces with Digital
// Microfluidics for Bacterial Transformation and Enzymatic
// Assays. Moazami et al., Anal. Chem. 2019, 91, 5159-5168.
// DOI: 10.1021/acs.analchem.8b05754
//
// Two protocols are encoded in sequence:
//
// PROTOCOL 1: Microscale Bacterial Co-Transformation (E. coli
//   DH5alpha with pFAB4876 [KanR] and pSB1C3-RFP [CamR]).
//   Heat-shock protocol: 42 C for 60s, then 4 C for 180s.
//   ITO-well-DMF configuration modelled (reagent-well refilling).
//   Three replicate droplets (1 uL each) are merged from:
//   competent cells + DNA plasmids + CaCl2 in equal volumes.
//
// PROTOCOL 2: Enzymatic Endoglucanase Assay.
//   Enzyme: endoglucanase (cleaves beta-1,4 glycosidic bonds).
//   Substrate: 4-methylumbelliferyl beta-D-cellobioside (MUC).
//   Three substrate concentrations (40, 20, 10 uM) dispensed
//   by serial dilution. Assay run at 30 C for 30 min.
//   Quenching: 0.3 M glycine-NaOH pH 11.0.
//   Readout: MUF fluorescence at 449 nm (excitation 368 nm).
//   All solutions contain 0.05% Pluronics F-68 additive.
//
// DROPLET VOLUMES: All unit droplets are ~1 uL, dispensed at
//   160 V_rms, 15 kHz. Reservoir target volume: 7 uL.
//   ITO-well-DMF: 400 uL bulk reagent in 3D-printed well;
//   ancillary reservoir refills main after every dispense.
//
// TEMPERATURE CONTROL: Closed-loop PID TEC (Kp=15, Ki=1.2,
//   Kd=0.5). Heat-shock zone: 42 C; cold zone: 4 C.
//   `heat` statements model TEC actuation.
//
// CFG STRUCTURE:
//   BB1  main             -- device init; transformation protocol
//   BB2  transformPass    -- transformSignal > 0: valid colonies;
//                           dispose and proceed to enzymatic assay
//   BB3  transformFail    -- transformSignal <= 0: no colonies; drain
//   BB4  transformJoin    -- join: enzymatic assay branch begins
//   BB5  assayPass        -- assaySignal > 0: valid fluorescence;
//                           dispose all assay droplets
//   BB6  assayFail        -- assaySignal <= 0: invalid; drain all
//   BB7  finalCleanup     -- terminal: dispose all QC signals
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 1: Dispense competent E. coli DH5alpha
//   cells (thawed on ice for 10 min before use).
//   1 uL unit droplet dispensed from main reservoir (7 uL).
//   In ITO-well-DMF: 400 uL bulk cells loaded in 3D well;
//   ancillary reservoir refills main after each dispense.
//
//   Three reagent droplets are dispensed independently and
//   then merged in steps 3-5.
// ------------------------------------------------------------

cellDroplet    = dispense 1 units of CompetentCells

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 2: Dispense plasmid DNA droplets.
//   pFAB4876: codes for GFP, selects on kanamycin (50 ug/mL).
//   pSB1C3-RFP: selects on chloramphenicol (35 ug/mL).
//   Each diluted to 1 ug/uL; 100 ng per reaction on-chip.
//   Co-transformation: both plasmids present simultaneously.
// ------------------------------------------------------------

dna1Droplet    = dispense 1 units of pFAB4876
dna2Droplet    = dispense 1 units of pSB1C3_RFP

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 3: Dispense CaCl2 solution.
//   Stock: 150 mM. Final concentration on-chip: 75 mM.
//   CaCl2 is critical for chemical competence and DNA uptake.
// ------------------------------------------------------------

cacl2Droplet   = dispense 1 units of CaCl2_Stock

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 4: Merge DNA plasmids first.
//   1 uL pFAB4876 + 1 uL pSB1C3-RFP merged on electrode
//   array at 160 V_rms, 15 kHz.
// ------------------------------------------------------------

dnaMix         = mix dna1Droplet with dna2Droplet for 5s

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 5: Merge cells + DNA mix.
//   Combined droplet now contains both plasmids and cells
//   in equal volume ratio (1:1:1:1 for 4-component merge).
// ------------------------------------------------------------

cellDnaMix     = mix cellDroplet with dnaMix for 5s

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 6: Add CaCl2 to complete transformation
//   mix. Final droplet (~4 uL) contains cells, pFAB4876,
//   pSB1C3-RFP, CaCl2 at 75 mM. Mixed for 10 s on-chip.
// ------------------------------------------------------------

transformMix   = mix cellDnaMix with cacl2Droplet for 10s

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 7: Heat shock - Phase 1 (42 C, 60 s).
//   TEC heats reaction zone to 42 C under closed-loop PID
//   control (Kp=15, Ki=1.2, Kd=0.5). Rise rate: 2.1 C/s.
//   Heat shock drives DNA uptake through transient membrane
//   pores in chemically competent DH5alpha cells.
// ------------------------------------------------------------

heat transformMix at 42c for 60s

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 8: Heat shock - Phase 2 (4 C, 180 s).
//   TEC rapidly cools to 4 C (rate: 1.01 C/s) to stop
//   membrane disruption and stabilise DNA-cell complex.
//   180 s = 3 min recovery at cold zone.
// ------------------------------------------------------------

heat transformMix at 4c for 180s

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 9: Post-transformation QC detection.
//   transformationQC module abstracts the off-chip colony
//   count step (agar plate with Kan+Cam selection, 37 C
//   overnight). On-chip: the merged droplet is sampled
//   post-heat-shock and checked for cell viability signal
//   as a proxy for transformation success.
//   Expected (PID + well): ~9.27e4 CFU/ug for co-transform.
// ------------------------------------------------------------

transformSignal = detect transformationQC on transformMix for 30s

// ============================================================
// BB2 / BB3: Transformation QC gate
// Pass (BB2): transformSignal > 0 -> viable transformed cells
//             detected; dispose and continue to assay branch.
// Fail (BB3): transformSignal <= 0 -> no viable signal; drain.
// Both branches converge at BB4 (transformJoin).
// ============================================================

if (transformSignal > 0) {
    dispose transformMix
} else {
    drain transformMix
}

// ============================================================
// BB4: transformJoin
// Dispose transformation QC signal. Control falls into
// enzymatic assay branch (BB5/BB6).
// ============================================================

dispose transformSignal

// ============================================================
// PROTOCOL 2: Enzymatic Endoglucanase Assay
// ============================================================

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 1: 40 uM assay droplet (1 unit substrate).
//   Dispensed directly into assay area 1. No dilution needed.
//   Buffer: 50 mM sodium-phosphate pH 7.0.
//   Substrate: 4-methylumbelliferyl beta-D-cellobioside (MUC).
//   In ITO-well-DMF: substrate reservoir refilled from 3D well.
//   All solutions contain 0.05% Pluronics F-68 additive.
// ------------------------------------------------------------

muc40uM_Assay  = dispense 1 units of MUC_Substrate

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 2: 20 uM assay droplet (direct dilution).
//   Dispense 1 unit of 40 uM MUC stock + 1 unit buffer.
//   Mix 1:1 -> 2-unit droplet at 20 uM. No split needed.
//   Concentration: (1 x 40 uM) / 2 units total = 20 uM. Correct.
//
//   NOTE ON COMPILER CONSTRAINT: lilott8/BioScript does not
//   support array zipping (multi-unit dispense does not produce
//   discrete array elements for enzyme/quench matching) and
//   split arrays leave stranded droplets if not fully consumed.
//   Direct dispense + mix avoids both failure modes entirely.
//   All three assay droplets are scalar; all downstream ops
//   are strict 1-to-1 with no array indexing required.
// ------------------------------------------------------------

muc40_for20    = dispense 1 units of MUC_Substrate
buffer_for20   = dispense 1 units of Buffer

muc20uM_Assay  = mix muc40_for20 with buffer_for20 for 5s

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 3: 10 uM assay droplet (direct dilution).
//   Dispense 1 unit of 40 uM MUC stock + 3 units buffer.
//   Mix -> 4-unit droplet at 10 uM. No split needed.
//   Concentration: (1 x 40 uM) / 4 units total = 10 uM. Correct.
// ------------------------------------------------------------

muc40_for10    = dispense 1 units of MUC_Substrate

// Three buffer droplets instantiated explicitly (compiler ignores
// multi-unit volume scalars; chaining is required to accumulate
// 3 units of buffer for the correct 1:3 dilution to 10 uM).
b1             = dispense 1 units of Buffer
b2             = dispense 1 units of Buffer
b3             = dispense 1 units of Buffer

b_mix_2        = mix b1 with b2 for 5s
b_mix_3        = mix b_mix_2 with b3 for 5s

// Final 1:3 dilution: (1 unit x 40 uM) / 4 units total = 10 uM.
muc10uM_Assay  = mix muc40_for10 with b_mix_3 for 5s

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 4: Dispense enzyme droplets.
//   Paper M&M: "a unit droplet of enzyme solution (~1 uL) was
//   dispensed into one of three assay areas." Each assay area
//   receives exactly 1 unit of enzyme regardless of substrate
//   volume. Enzyme concentration is held constant across all
//   three substrate concentration conditions (paper Fig. 5c
//   caption: "enzyme concentration remaining constant").
//   In ITO-well-DMF: enzyme reservoir refilled from 3D well
//   after each dispense (ancillary reservoir refill sequence).
// ------------------------------------------------------------

enzymeDrop40   = dispense 1 units of EndoglucanaseEnzyme
enzymeDrop20   = dispense 1 units of EndoglucanaseEnzyme
enzymeDrop10   = dispense 1 units of EndoglucanaseEnzyme

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 5: Start reactions.
//   Merge enzyme into each substrate assay area.
//   Paper M&M: "all three substrate-containing droplets were
//   simultaneously mixed with the enzyme droplets in the
//   assay areas." TEC activates for closed-loop 30 C control
//   (Kp=15, Ki=1.2, Kd=0.5).
// ------------------------------------------------------------

reaction40uM   = mix muc40uM_Assay with enzymeDrop40 for 5s
reaction20uM   = mix muc20uM_Assay with enzymeDrop20 for 5s
reaction10uM   = mix muc10uM_Assay with enzymeDrop10 for 5s

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 6: Incubate at 30 C for 30 min (1800 s).
//   Endoglucanase cleaves the beta-(1,4) glycosidic bond in
//   MUC, releasing 4-methylumbelliferone (MUF) fluorophore.
//   Closed-loop PID TEC maintains 30 C steady state.
//   All three reactions run concurrently in separate assay
//   areas on the same DMF device.
// ------------------------------------------------------------

heat reaction40uM at 30c for 30m
heat reaction20uM at 30c for 30m
heat reaction10uM at 30c for 30m

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 7: Quench reactions.
//   Quenching solution: 0.3 M glycine-NaOH, pH 11.0.
//   1 uL quench droplet merged with each 1 uL reaction droplet
//   in its assay area. Quenching stops enzymatic activity and
//   enhances MUF fluorescence at alkaline pH.
// ------------------------------------------------------------

// Quench: 1 unit per assay area regardless of substrate volume.
// Paper M&M: "a unit droplet of quenching solution (0.3 M
// glycine-NaOH, pH 11.0) was mixed with each reaction droplet."
quench40       = dispense 1 units of QuenchingSolution
quench20       = dispense 1 units of QuenchingSolution
quench10       = dispense 1 units of QuenchingSolution

quenched40uM   = mix reaction40uM with quench40 for 5s
quenched20uM   = mix reaction20uM with quench20 for 5s
quenched10uM   = mix reaction10uM with quench10 for 5s

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 8: Fluorescence detection.
//   endoglucanaseDetection module abstracts the CLARIOStar
//   plate reader readout (off-chip step; device placed on
//   96-well plate). MUF emission at 449 nm, excitation 368 nm.
//   Well-scan: 15x15 matrix, 6 mm diameter, focal height 4.0 mm.
//   Maximum fluorescence per droplet recorded.
//   QC gate uses 40 uM droplet (highest expected signal).
// ------------------------------------------------------------

assaySignal40  = detect endoglucanaseDetection on quenched40uM for 30s
assaySignal20  = detect endoglucanaseDetection on quenched20uM for 30s
assaySignal10  = detect endoglucanaseDetection on quenched10uM for 30s

// ============================================================
// BB5 / BB6: Assay QC gate (keyed on 40 uM signal; highest)
// Pass (BB5): assaySignal40 > 0 -> valid MUF fluorescence;
//             dispose all three quenched reaction droplets.
// Fail (BB6): assaySignal40 <= 0 -> no signal (enzyme inactive
//             or reagent failure); drain all.
// Both branches converge at BB7 (finalCleanup).
// ============================================================

if (assaySignal40 > 0) {
    dispose quenched40uM
    dispose quenched20uM
    dispose quenched10uM
} else {
    drain quenched40uM
    drain quenched20uM
    drain quenched10uM
}

// ============================================================
// BB7: finalCleanup (terminal)
// Dispose all three assay QC signal droplets.
// Experiment ends.
// ============================================================

dispose assaySignal40
dispose assaySignal20
dispose assaySignal10

// [terminal -- no further instructions; exit node for CFG]

module fluorescence

manifest leaf_tissue
manifest trichloroacetic_acid
manifest tba_reagent

instructions:

// Step 1: Grind leaf tissue (control or infected) with liquid nitrogen, then homogenize
// 100 mg powder with 1 mL of 0.1% (w/v) TCA
tissue = dispense 100 units of leaf_tissue
tca = dispense 1000 units of trichloroacetic_acid
homogenate = mix tissue with tca

// Step 2: Centrifugation (12,000 x g, 15 min, 4 C) is off-chip; supernatant is carried forward

// Step 3: Combine 1 mL of 0.5% TBA in 20% TCA with 0.5 mL of the supernatant
tba = dispense 1000 units of tba_reagent
reaction = mix homogenate with tba

// Step 4: Heat at 95 C for 30 min (dry bath), then cool at ice-cold temperature
heat reaction at 95c for 30m
heat reaction at 4c for 5m

// Step 5: Second centrifugation (14,000 x g, 15 min, 4 C) is off-chip; supernatant carried forward

// Step 6: Measure absorbance at 532 nm (TBARS signal) and 600 nm (turbidity correction);
// A600 is subtracted from A532 downstream to give corrected absorbance
// (detect fluorescence used as the generic optical-signal readout stand-in, since BioScript
// exposes no dedicated absorbance/spectrophotometric detect module)
abs_532 = detect fluorescence on reaction for 30s
abs_600 = detect fluorescence on reaction for 30s

dispose reaction

module separationEfficiencyDetection
module cellViabilityDetection
module antibodyTiterDetection
module cellCycleDetection

manifest CHO_Cells
manifest Yeast_S_cerevisiae
manifest Hybridoma_Cells
manifest PBS
manifest PDMS_PrimingBuffer
manifest PropidiumIodide
manifest FDAStain
manifest HoechstStain
manifest TrypanBlue
manifest IgG_ELISA_Reagent
manifest CompleteDMEM
manifest ConditionedMedia
manifest TrypsinEDTA
manifest BSA_EDTA_Buffer

instructions:

// ============================================================
// Membrane-less Microfiltration Using Inertial Microfluidics
// Warkiani, Tay, Guan & Han - Scientific Reports 5:11018 (2015)
// DOI: 10.1038/srep11018
//
// Protocol: Massively parallelised spiral inertial microfluidic
// device (~200 individual spiral microchannels, PDMS, trapezoidal
// cross-section) for continuous, membrane-less, size-based cell
// filtration at macroscopic flow rates (~500 mL/min combined).
//
// Three applications are encoded in sequence:
//   1. CHO cell retention from perfusion bioreactor (filtration mode)
//   2. Yeast (S. cerevisiae) microfiltration (filtration mode)
//   3. CHO cell cycle synchronisation (fractionation mode)
//
// WORKING PRINCIPLE:
//   Inertial lift force (F_L ~ a_p^4) and Dean drag force
//   (F_D ~ a_p^2) act on particles in curvilinear channels.
//   Trapezoidal cross-section creates stronger Dean vortex cores
//   near the outer wall, trapping all particles at the outer
//   outlet (filtration mode, ~6 mL/min per spiral) or focusing
//   small cells near outer wall and large cells near inner wall
//   (fractionation mode, ~1.5-2 mL/min per spiral).
//
// DEVICE GEOMETRY (CHO):
//   8-loop spiral, radius 8-24 mm, channel 600 um wide x
//   80x130 um trapezoidal cross-section; 4 spirals per PDMS
//   layer, multiplexed to 84 spirals for 500 mL/min throughput.
//
// DEVICE GEOMETRY (Yeast):
//   Channel 450 um wide x 30x70 um trapezoidal cross-section;
//   8 spirals per layer; 180 spirals for ~320 mL/min.
//
// ABSTRACTION NOTE:
//   `mix` steps abstract hydrodynamic inertial focusing events
//   (pressure-driven flow through spiral microchannels), not
//   DMF electrode mixing. Duration encodes residence time /
//   processing time at the stated flow rate.
//   `heat` steps encode incubation / culture conditions.
//
// CFG STRUCTURE:
//   BB1  main               -- device priming; CHO filtration loop
//   BB2  choRetentionPass   -- choSignal > 0: >95% efficiency,
//                              return cells; continue culture
//   BB3  choRetentionFail   -- choSignal <= 0: low efficiency; drain
//   BB4  choRetentionJoin   -- join: viability QC branch
//   BB5  viabilityPass      -- viabilitySignal > 0: >90% viability; dispose
//   BB6  viabilityFail      -- viabilitySignal <= 0: low viability; drain
//   BB7  viabilityJoin      -- join: IgG titer QC branch
//   BB8  titerPass          -- titerSignal > 0: IgG rising; dispose
//   BB9  titerFail          -- titerSignal <= 0: no IgG detected; drain
//   BB10 titerJoin          -- join: yeast filtration branch begins
//   BB11 yeastPass          -- yeastSignal > 0: >90% efficiency; dispose
//   BB12 yeastFail          -- yeastSignal <= 0: low efficiency; drain
//   BB13 yeastJoin          -- join: cell cycle synchronisation branch
//   BB14 syncPass           -- syncSignal > 0: G0/G1:G2/M >= 5:1; dispose
//   BB15 syncFail           -- syncSignal <= 0: poor enrichment; drain
//   BB16 finalCleanup       -- terminal: dispose all QC signals
// ============================================================

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// APPLICATION 1: CHO CELL RETENTION FROM PERFUSION BIOREACTOR
// ------------------------------------------------------------

// ------------------------------------------------------------
// STEP 1: Prime the spiral microfluidic device with PBS to
//         wet the PDMS microchannels and eliminate air bubbles.
//         PDMS surface must be fully wetted before cell loading
//         to prevent non-specific cell adhesion and bubble-
//         induced channel blockage. ~2 mL PBS per device at
//         6 mL/min for 20 s. BSA-EDTA supplemented buffer is
//         used to prevent non-specific adsorption to PDMS walls
//         (0.5% BSA, 2 mM EDTA in 1x PBS).
//         NOTE: `mix` abstracts pressure-driven channel priming.
// ------------------------------------------------------------

primingBuffer  = dispense 1 units of BSA_EDTA_Buffer
primingPBS     = dispense 1 units of PBS
primingMix     = mix primingBuffer with primingPBS for 20s

// ------------------------------------------------------------
// STEP 2: Prepare CHO cell suspension from spinner flask
//         bioreactor (AE-1 hybridoma cell line, ATCC HB-72).
//         Cells cultured in Hybridoma-SFM at 37 C / 5% CO2,
//         100 rpm magnetic stir. Working concentration:
//         1e4 - 1e7 cells/mL in BSA-EDTA buffer. Separation
//         efficiency remains >95% up to 1e7 cells/mL; declines
//         above this threshold (Fig. 2b).
//         Cells resuspended in BSA-EDTA buffer to prevent
//         agglomeration and wall adsorption.
// ------------------------------------------------------------

choCells       = dispense 1 units of CHO_Cells
bsaBuffer1     = dispense 1 units of BSA_EDTA_Buffer
choSuspension  = mix choCells with bsaBuffer1 for 10s

// ------------------------------------------------------------
// STEP 3: Load CHO cell suspension into multiplexed inertial
//         filtration system via peristaltic pump (Masterflex,
//         Cole-Parmer). Flow rate: 6 mL/min per single spiral
//         (optimised from 1-10 mL/min range, Fig. 2b).
//         84 spirals multiplexed -> 500 mL/min combined.
//         At 6 mL/min (filtration mode): inertial lift forces
//         dominate; all cells focus near outer wall and exit
//         via outer outlet (cell concentrate / recycle stream).
//         Clarified culture medium exits via inner outlet
//         (cell-free filtrate for product harvest).
//         NOTE: `mix` abstracts inertial focusing through the
//         8-loop spiral microchannel at the stated flow rate.
//         Duration = residence time in device at 6 mL/min.
// ------------------------------------------------------------

choFiltered    = mix choSuspension with primingMix for 5s

// Post-separation: detect separation efficiency using inline
// flow cytometry or cell counter. >95% efficiency expected
// at 6 mL/min with <1e7 cells/mL.
choSignal      = detect separationEfficiencyDetection on choFiltered for 30s

// ============================================================
// BB2 / BB3: CHO retention QC gate
// Pass (BB2): choSignal > 0 -> >95% separation efficiency;
//             enriched cell fraction returned to bioreactor
//             flask; fresh media replenished; dispose filtrate.
// Fail (BB3): choSignal <= 0 -> separation efficiency dropped
//             (likely due to concentration >1e7 cells/mL);
//             drain and adjust cell concentration.
// Both branches converge at BB4 (choRetentionJoin).
// ============================================================

if (choSignal > 0) {
    // Enriched CHO cells returned to spinner flask bioreactor.
    // Fresh complete media added to maintain volume and nutrients.
    freshMedia     = dispense 1 units of CompleteDMEM
    recycledCells  = mix choFiltered with freshMedia for 1m

    // Continue perfusion culture: 37 C / 5% CO2.
    // Daily microfiltration cycles performed over 10-day run.
    // Media replaced, cells recycled each cycle.
    heat recycledCells at 37c for 1440m

    dispose recycledCells
} else {
    drain choFiltered
}

// ============================================================
// BB4: choRetentionJoin
// Dispose CHO separation QC signal. Continue to viability
// assessment branch (BB5/BB6).
// ============================================================

dispose choSignal

// ------------------------------------------------------------
// STEP 4: Cell viability assessment post-inertial filtration.
//         Hybridoma cells processed at 6 mL/min per spiral
//         (residence time <0.1 s). Cells stained with
//         propidium iodide (PI) for dead cell identification
//         (excluded by intact membranes in live cells) and
//         FDA (fluorescein diacetate) for live cell
//         identification (ex 490 nm / em 526 nm).
//         Viability measured by trypan blue exclusion and
//         propidium iodide via flow cytometry.
//         Expected: >90% viability post-separation (Fig. 2c).
//         c-FOS gene expression confirms no shear-stress
//         upregulation (short residence time <0.1 s prevents
//         AP-1 pathway activation compared to CHX control).
// ------------------------------------------------------------

hybridoma      = dispense 1 units of Hybridoma_Cells
piStain        = dispense 1 units of PropidiumIodide
fdaStain       = dispense 1 units of FDAStain

// Trypan blue exclusion to measure live/dead ratio.
trypan         = dispense 1 units of TrypanBlue
trypanMix      = mix hybridoma with trypan for 2m

// PI / FDA dual staining for flow cytometry viability analysis.
piMix          = mix trypanMix with piStain for 5m
viabilitySample = mix piMix with fdaStain for 10m

viabilitySignal = detect cellViabilityDetection on viabilitySample for 30s

// ============================================================
// BB5 / BB6: Viability QC gate
// Pass (BB5): viabilitySignal > 0 -> >90% viable post-sort;
//             confirms inertial filtration does not perturb
//             cellular homeostasis; dispose stained sample.
// Fail (BB6): viabilitySignal <= 0 -> <90% viability;
//             indicates cellular damage; drain and investigate.
// Both branches converge at BB7 (viabilityJoin).
// ============================================================

if (viabilitySignal > 0) {
    dispose viabilitySample
} else {
    drain viabilitySample
}

// ============================================================
// BB7: viabilityJoin
// Dispose viability QC signal. Continue to IgG titer branch.
// ============================================================

dispose viabilitySignal

// ------------------------------------------------------------
// STEP 5: IgG antibody titer monitoring (Fig. 2d).
//         Media samples collected from spinner flask daily
//         and assessed for IgG1 production by ELISA (Abcam
//         IgG1 ELISA protocol, Cat. ab100548). Titer expected
//         to increase steadily over 10-day run (0-50 ug/mL),
//         confirming that cellular activities involved in IgG
//         production are minimally affected by inertial
//         filtration. Both post-sorted and unsorted control
//         hybridoma cells show similar proliferation and
//         production rates with no significant decline.
// ------------------------------------------------------------

mediaSample    = dispense 1 units of ConditionedMedia
elisaReagent   = dispense 1 units of IgG_ELISA_Reagent
elisaMix       = mix mediaSample with elisaReagent for 30m

// ELISA incubation: 37 C for 30 min per Abcam protocol.
heat elisaMix at 37c for 30m

titerSignal    = detect antibodyTiterDetection on elisaMix for 30s

// ============================================================
// BB8 / BB9: IgG titer QC gate
// Pass (BB8): titerSignal > 0 -> IgG detected and increasing;
//             confirms productive perfusion culture; dispose.
// Fail (BB9): titerSignal <= 0 -> no IgG detected; culture
//             may have failed; drain and investigate.
// Both branches converge at BB10 (titerJoin).
// ============================================================

if (titerSignal > 0) {
    dispose elisaMix
} else {
    drain elisaMix
}

// ============================================================
// BB10: titerJoin
// Dispose titer QC signal. Continue to yeast filtration.
// ============================================================

dispose titerSignal

// ============================================================
// APPLICATION 2: YEAST (S. CEREVISIAE) MICROFILTRATION
// ============================================================

// ------------------------------------------------------------
// STEP 6: Prepare yeast suspension.
//         Dry strain of Saccharomyces cerevisiae (Sigma-Aldrich)
//         rehydrated in water at 35 C for 10 min with stirring.
//         Centrifuged at 2000 g for 15 min, washed twice with
//         distilled water to remove cell debris. Pellet
//         resuspended in BSA-EDTA running buffer.
//         Average yeast cell size: 3-5 um.
//         Working concentration: 0.05-1 g/L (1e5 cells/mL for
//         >90% efficiency; up to 1 g/L with reasonable
//         performance in single cycle, Fig. 3b).
//         Device geometry: 450 um wide x 30x70 um trapezoidal
//         cross-section; optimised for 3-5 um particle focusing
//         near outer wall at 2 mL/min per spiral.
// ------------------------------------------------------------

yeastCells     = dispense 1 units of Yeast_S_cerevisiae
bsaBuffer2     = dispense 1 units of BSA_EDTA_Buffer
yeastSuspension = mix yeastCells with bsaBuffer2 for 10s

// ------------------------------------------------------------
// STEP 7: Inertial microfiltration of yeast suspension.
//         Flow rate: 2 mL/min per single spiral (optimised).
//         Multiplexed system: 180 spirals -> ~320 mL/min.
//         At 2 mL/min, yeast cells (3-5 um) focus near the
//         outer wall via Dean vortex trapping (trapezoidal
//         30x70 um channel). Cells exit via outer outlet as
//         concentrated yeast fraction; clarified broth
//         (cell-free) exits via inner outlet.
//         This enables continuous broth fermentation
//         clarification without membrane fouling.
//         NOTE: `mix` abstracts pressure-driven inertial
//         focusing through the small-dimension yeast spiral
//         at 2 mL/min. Duration = transit / processing time.
// ------------------------------------------------------------

yeastPriming   = dispense 1 units of PBS
yeastFiltered  = mix yeastSuspension with yeastPriming for 5s

// Separation efficiency measured by flow cytometry (BD LSR II).
// Scatter plots (SSC-A vs FSC-A) used to gate yeast population
// at inlet, outer outlet, inner outlet (Fig. 3a).
// Expected: >90% efficiency at 1e5 cells/mL (0.05 g/L).
// Performance benchmarked against cellulose acetate and Teflon
// membrane filters in cross-flow mode (Fig. 3c): inertial
// system maintains constant flux throughout filtration run
// while membrane flux declines due to progressive fouling.
yeastSignal    = detect separationEfficiencyDetection on yeastFiltered for 30s

// ============================================================
// BB11 / BB12: Yeast filtration QC gate
// Pass (BB11): yeastSignal > 0 -> >90% separation efficiency;
//              yeast concentrate fraction collected for
//              downstream use; dispose clarified broth.
// Fail (BB12): yeastSignal <= 0 -> efficiency dropped (likely
//              high concentration >1 g/L or channel clogging);
//              drain and re-run with lower concentration or
//              additional sorting cycles.
// Both branches converge at BB13 (yeastJoin).
// ============================================================

if (yeastSignal > 0) {
    dispose yeastFiltered
} else {
    drain yeastFiltered
}

// ============================================================
// BB13: yeastJoin
// Dispose yeast separation QC signal. Continue to CHO
// cell cycle synchronisation branch.
// ============================================================

dispose yeastSignal

// ============================================================
// APPLICATION 3: CHO CELL CYCLE SYNCHRONISATION (FRACTIONATION)
// ============================================================

// ------------------------------------------------------------
// STEP 8: Prepare asynchronous CHO-K1 cell suspension for
//         cell cycle synchronisation via inertial fractionation.
//         CHO-K1 (ATCC CCL-61) cultured in low-glucose DMEM +
//         10% FBS + 1% pen/strep at 37 C / 5% CO2.
//         Sub-confluent monolayers dissociated with 0.01%
//         trypsin + 5.3 mM EDTA (Lonza).
//         Cells resuspended in BSA-EDTA buffer at 1e6 cells/mL.
//
//         SIZE BASIS OF SYNCHRONISATION:
//         G0/G1 cells: 11 +/- 2 um (smaller)
//         G2/M cells:  18 +/- 2 um (larger)
//         Initial asynchronous G0/G1:G2/M ratio: 1.82:1.
//         (Fig. 4a, Hoechst DNA staining by FACS).
//
//         FRACTIONATION MODE (vs filtration mode):
//         At low flow rate (~1.5-2 mL/min per spiral), inertial
//         lift and Dean drag reach separate equilibria for the
//         two cell size populations:
//           - Small cells (G0/G1, <14 um): trapped near outer
//             wall -> exit via outer outlet (enriched G0/G1)
//           - Large cells (G2/M, >14 um): focused near inner
//             wall -> exit via inner outlet (enriched G2/M)
//         NOTE: Same device geometry as CHO filtration (600 um
//         wide x 80x130 um trapezoidal); only flow rate changed.
// ------------------------------------------------------------

choSyncCells   = dispense 1 units of CHO_Cells
trypsin        = dispense 1 units of TrypsinEDTA

// Trypsin dissociation of adherent CHO-K1 monolayer.
detachedCells  = mix choSyncCells with trypsin for 3m

// Quench trypsin with complete DMEM; pellet and resuspend
// in BSA-EDTA buffer at 1e6 cells/mL.
quenchMedia    = dispense 1 units of CompleteDMEM
bsaBuffer3     = dispense 1 units of BSA_EDTA_Buffer

quenchedCells  = mix detachedCells with quenchMedia for 2m
syncSuspension = mix quenchedCells with bsaBuffer3 for 5s

// ------------------------------------------------------------
// STEP 9: Inertial fractionation for cell cycle synchronisation.
//         Flow rate: 1.5 mL/min per spiral (fractionation mode).
//         Multiplexed system: 150-200 spirals -> 150-300 mL/min
//         (sufficient to fractionate 1-5 L perfusion reactor
//         contents within minutes).
//         At this low flow rate, Dean number is reduced;
//         smaller G0/G1 cells remain trapped in Dean vortex
//         near outer wall while larger G2/M cells migrate to
//         inner wall equilibrium position.
//         Throughput per spiral: 1-2 mL/min (up to 1e6 cells/mL).
//         Multiple sorting rounds improve G0/G1 enrichment:
//         1 round: G0/G1:G2/M ratio -> 5.02:1 (outer outlet)
//         G0/G1 purity: ~80% in outer outlet (from ~60% input).
//         NOTE: `mix` abstracts the size-differential inertial
//         focusing event at low flow rate fractionation regime.
// ------------------------------------------------------------

syncPriming    = dispense 1 units of PBS
fractionatedCells = mix syncSuspension with syncPriming for 8s

// ------------------------------------------------------------
// STEP 10: Cell cycle phase analysis by Hoechst DNA staining
//          and flow cytometry (FACS).
//          Sorted cells fixed in 4% PFA (15 min at 4 C),
//          pelleted at 600 g for 5 min, stained with:
//            - 10 ug/mL RNase (i-DNA Biotechnology) to remove RNA
//            - 3.8 mM sodium citrate
//            - Hoechst NucBlue LiveReadyProbes (Invitrogen)
//          in 1x PBS for 30 min at room temperature (25 C).
//          DNA content measured by BD LSR II flow cytometer.
//          G0/G1 (2N DNA, low Hoechst signal) and G2/M (4N DNA,
//          high Hoechst signal) peaks distinguished by FACS.
//          Data analysed with FlowJo software.
// ------------------------------------------------------------

hoechstStain   = dispense 1 units of HoechstStain
bsaBuffer4     = dispense 1 units of BSA_EDTA_Buffer

// Fix cells in PBS at 4 C for 15 min.
heat fractionatedCells at 4c for 15m

stainBuffer    = mix fractionatedCells with bsaBuffer4 for 5s
stainedSync    = mix stainBuffer with hoechstStain for 30m

syncSignal     = detect cellCycleDetection on stainedSync for 30s

// ============================================================
// BB14 / BB15: Cell cycle synchronisation QC gate
// Pass (BB14): syncSignal > 0 -> G0/G1:G2/M ratio >= 5:1 in
//              outer outlet fraction; G0/G1 purity ~80%;
//              synchronised cells suitable for downstream
//              anti-cancer drug screening or recombinant
//              protein production (faster-growing G1 phase).
//              Dispose stained cell sample after FACS readout.
// Fail (BB15): syncSignal <= 0 -> insufficient enrichment
//              (<3-fold improvement); drain and repeat
//              fractionation with additional sorting rounds
//              (inner outlet fraction from round 1 can be
//              re-processed as described in paper).
// Both branches converge at BB16 (finalCleanup).
// ============================================================

if (syncSignal > 0) {
    // Synchronised G0/G1 cells collected at outer outlet for
    // re-inoculation into bioreactor or drug screening assay.
    // Cells recovered in conditioned media and transferred
    // to culture vessel for downstream characterisation.
    conditionedMedia2 = dispense 1 units of ConditionedMedia
    synchronisedCells = mix stainedSync with conditionedMedia2 for 1m

    // Return synchronised cells to 37 C culture for downstream use.
    heat synchronisedCells at 37c for 60m

    dispose synchronisedCells
} else {
    drain stainedSync
}

// ============================================================
// BB16: finalCleanup (terminal)
// Dispose all remaining QC signal droplets.
// Experiment ends.
// ============================================================

dispose syncSignal

// [terminal -- no further instructions; exit node for CFG]
